("fierydance", "Fiery Dance", "Fire", "Special", 80, "100", 10, 0, "normal", "Has a 50% chance to raise the user\'s Special Attack by 1 stage.", "50% chance to raise the user\'s Sp. Atk by 1.", "{\'protect\':1,\'mirror\':1,\'dance\':1,\'metronome\':1}", "{\'chance\':50,\'self\':{\'boosts\':{\'spa\':1}}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':552,\'accuracy\':100,\'basePower\':80,\'category\':\'Special\',\'name\':\'Fiery Dance\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'dance\':1,\'metronome\':1},\'secondary\':{\'chance\':50,\'self\':{\'boosts\':{\'spa\':1}}},\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Beautiful\',\'desc\':\'Has a 50% chance to raise the user\'s Special Attack by 1 stage.\',\'shortDesc\':\'50% chance to raise the user\'s Sp. Atk by 1.\'}"),
("fierywrath", "Fiery Wrath", "Dark", "Special", 90, "100", 10, 0, "allAdjacentFoes", "Has a 20% chance to make the target flinch.", "20% chance to make the foe(s) flinch.", "{\'protect\':1,\'mirror\':1}", "{\'chance\':20,\'volatileStatus\':\'flinch\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':822,\'accuracy\':100,\'basePower\':90,\'category\':\'Special\',\'name\':\'Fiery Wrath\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1},\'secondary\':{\'chance\':20,\'volatileStatus\':\'flinch\'},\'target\':\'allAdjacentFoes\',\'type\':\'Dark\',\'desc\':\'Has a 20% chance to make the target flinch.\',\'shortDesc\':\'20% chance to make the foe(s) flinch.\'}"),
("filletaway", "Fillet Away", "Normal", "Status", 0, "1", 10, 0, "self", "Raises the user\'s Attack, Special Attack, and Speed by 2 stages in exchange for the user losing 1/2 of its maximum HP, rounded down. Fails if the user would faint or if its Attack, Special Attack, and Speed stat stages would not change.", "+2 Attack, Sp. Atk, Speed for 1/2 user\'s max HP.", "{\'snatch\':1}", NULL, NULL, NULL, "{\'atk\':2,\'spa\':2,\'spe\':2}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':868,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Fillet Away\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1},\'boosts\':{\'atk\':2,\'spa\':2,\'spe\':2},\'target\':\'self\',\'type\':\'Normal\',\'desc\':\'Raises the user\'s Attack, Special Attack, and Speed by 2 stages in exchange for the user losing 1\\/2 of its maximum HP, rounded down. Fails if the user would faint or if its Attack, Special Attack, and Speed stat stages would not change.\',\'shortDesc\':\'+2 Attack, Sp. Atk, Speed for 1\\/2 user\'s max HP.\'}"),
("finalgambit", "Final Gambit", "Fighting", "Special", 0, "100", 5, 0, "normal", "Deals damage to the target equal to the user\'s current HP. If this move is successful, the user faints.", "Does damage equal to the user\'s HP. User faints.", "{\'protect\':1,\'metronome\':1,\'noparentalbond\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':515,\'accuracy\':100,\'basePower\':0,\'selfdestruct\':\'ifHit\',\'category\':\'Special\',\'name\':\'Final Gambit\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'metronome\':1,\'noparentalbond\':1},\'target\':\'normal\',\'type\':\'Fighting\',\'zMove\':{\'basePower\':180},\'contestType\':\'Tough\',\'desc\':\'Deals damage to the target equal to the user\'s current HP. If this move is successful, the user faints.\',\'shortDesc\':\'Does damage equal to the user\'s HP. User faints.\'}"),
("fireblast", "Fire Blast", "Fire", "Special", 110, "85", 5, 0, "normal", "Has a 10% chance to burn the target.", "10% chance to burn the target.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':10,\'status\':\'brn\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':126,\'accuracy\':85,\'basePower\':110,\'category\':\'Special\',\'name\':\'Fire Blast\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':10,\'status\':\'brn\'},\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Beautiful\',\'desc\':\'Has a 10% chance to burn the target.\',\'shortDesc\':\'10% chance to burn the target.\'}"),
("firefang", "Fire Fang", "Fire", "Physical", 65, "95", 15, 0, "normal", "Has a 10% chance to burn the target and a 10% chance to make it flinch.", "10% chance to burn. 10% chance to flinch.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'bite\':1}", NULL, "[{\'chance\':10,\'status\':\'brn\'},{\'chance\':10,\'volatileStatus\':\'flinch\'}]", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':424,\'accuracy\':95,\'basePower\':65,\'category\':\'Physical\',\'name\':\'Fire Fang\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'bite\':1},\'secondaries\':[{\'chance\':10,\'status\':\'brn\'},{\'chance\':10,\'volatileStatus\':\'flinch\'}],\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Cool\',\'desc\':\'Has a 10% chance to burn the target and a 10% chance to make it flinch.\',\'shortDesc\':\'10% chance to burn. 10% chance to flinch.\'}");
INSERT INTO `api_moves` (`id`, `name`, `type`, `category`, `basePower`, `accuracy`, `pp`, `priority`, `target`, `desc`, `shortDesc`, `flags`, `secondary`, `secondaries`, `drain`, `boosts`, `self`, `selfBoost`, `condition`, `volatileStatus`, `status`, `weather`, `terrain`, `pseudoWeather`, `heal`, `recoil`, `multihit`, `raw_json`) VALUES
("firelash", "Fire Lash", "Fire", "Physical", 80, "100", 15, 0, "normal", "Has a 100% chance to lower the target\'s Defense by 1 stage.", "100% chance to lower the target\'s Defense by 1.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':100,\'boosts\':{\'def\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':680,\'accuracy\':100,\'basePower\':80,\'category\':\'Physical\',\'name\':\'Fire Lash\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':100,\'boosts\':{\'def\':-1}},\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Cute\',\'desc\':\'Has a 100% chance to lower the target\'s Defense by 1 stage.\',\'shortDesc\':\'100% chance to lower the target\'s Defense by 1.\'}"),
("firepledge", "Fire Pledge", "Fire", "Special", 80, "100", 10, 0, "normal", "If one of the user\'s allies chose to use Grass Pledge or Water Pledge this turn and has not moved yet, it takes its turn immediately after the user and the user\'s move does nothing. If combined with Grass Pledge, the ally uses Fire Pledge with 150 power and a sea of fire appears on the target\'s side for 4 turns, which causes damage to non-Fire types equal to 1/8 of their maximum HP, rounded down, at the end of each turn during effect, including the last turn. If combined with Water Pledge, the ally uses Water Pledge with 150 power and a rainbow appears on the user\'s side for 4 turns, which doubles secondary effect chances and stacks with the Serene Grace Ability, except effects that cause flinching can only have their chance doubled once. When used as a combined move, this move gains STAB no matter what the user\'s type is. This move does not consume the user\'s Fire Gem.", "Use with Grass or Water Pledge for added effect.", "{\'protect\':1,\'mirror\':1,\'nonsky\':1,\'metronome\':1,\'pledgecombo\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':4,\'onResidualOrder\':5,\'onResidualSubOrder\':1,\'onSideResidualOrder\':26,\'onSideResidualSubOrder\':8}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':519,\'accuracy\':100,\'basePower\':80,\'basePowerCallback\':true,\'category\':\'Special\',\'name\':\'Fire Pledge\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'nonsky\':1,\'metronome\':1,\'pledgecombo\':1},\'condition\':{\'duration\':4,\'onResidualOrder\':5,\'onResidualSubOrder\':1,\'onSideResidualOrder\':26,\'onSideResidualSubOrder\':8},\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Beautiful\',\'desc\':\'If one of the user\'s allies chose to use Grass Pledge or Water Pledge this turn and has not moved yet, it takes its turn immediately after the user and the user\'s move does nothing. If combined with Grass Pledge, the ally uses Fire Pledge with 150 power and a sea of fire appears on the target\'s side for 4 turns, which causes damage to non-Fire types equal to 1\\/8 of their maximum HP, rounded down, at the end of each turn during effect, including the last turn. If combined with Water Pledge, the ally uses Water Pledge with 150 power and a rainbow appears on the user\'s side for 4 turns, which doubles secondary effect chances and stacks with the Serene Grace Ability, except effects that cause flinching can only have their chance doubled once. When used as a combined move, this move gains STAB no matter what the user\'s type is. This move does not consume the user\'s Fire Gem.\',\'shortDesc\':\'Use with Grass or Water Pledge for added effect.\'}"),
("firepunch", "Fire Punch", "Fire", "Physical", 75, "100", 15, 0, "normal", "Has a 10% chance to burn the target.", "10% chance to burn the target.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'punch\':1,\'metronome\':1}", "{\'chance\':10,\'status\':\'brn\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':7,\'accuracy\':100,\'basePower\':75,\'category\':\'Physical\',\'name\':\'Fire Punch\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'punch\':1,\'metronome\':1},\'secondary\':{\'chance\':10,\'status\':\'brn\'},\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Tough\',\'desc\':\'Has a 10% chance to burn the target.\',\'shortDesc\':\'10% chance to burn the target.\'}"),
("firespin", "Fire Spin", "Fire", "Special", 35, "85", 15, 0, "normal", "Prevents the target from switching for four or five turns (seven turns if the user is holding Grip Claw). Causes damage to the target equal to 1/8 of its maximum HP (1/6 if the user is holding Binding Band), rounded down, at the end of each turn during effect. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Flip Turn, Parting Shot, Shed Tail, Teleport, U-turn, or Volt Switch. The effect ends if either the user or the target leaves the field, or if the target uses Mortal Spin, Rapid Spin, or Substitute successfully. This effect is not stackable or reset by using this or another binding move.", "Traps and damages the target for 4-5 turns.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "partiallytrapped", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':83,\'accuracy\':85,\'basePower\':35,\'category\':\'Special\',\'name\':\'Fire Spin\',\'pp\':15,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'volatileStatus\':\'partiallytrapped\',\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Beautiful\',\'desc\':\'Prevents the target from switching for four or five turns (seven turns if the user is holding Grip Claw). Causes damage to the target equal to 1\\/8 of its maximum HP (1\\/6 if the user is holding Binding Band), rounded down, at the end of each turn during effect. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Flip Turn, Parting Shot, Shed Tail, Teleport, U-turn, or Volt Switch. The effect ends if either the user or the target leaves the field, or if the target uses Mortal Spin, Rapid Spin, or Substitute successfully. This effect is not stackable or reset by using this or another binding move.\',\'shortDesc\':\'Traps and damages the target for 4-5 turns.\'}"),
("firstimpression", "First Impression", "Bug", "Physical", 90, "100", 10, 2, "normal", "Fails unless it is the user\'s first turn on the field.", "Nearly always goes first. First turn out only.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':660,\'accuracy\':100,\'basePower\':90,\'category\':\'Physical\',\'name\':\'First Impression\',\'pp\':10,\'priority\':2,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Bug\',\'contestType\':\'Cute\',\'desc\':\'Fails unless it is the user\'s first turn on the field.\',\'shortDesc\':\'Nearly always goes first. First turn out only.\'}"),
("fishiousrend", "Fishious Rend", "Water", "Physical", 85, "100", 10, 0, "normal", "Power doubles if the user moves before the target.", "Power doubles if user moves before the target.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'bite\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':755,\'accuracy\':100,\'basePower\':85,\'basePowerCallback\':true,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Fishious Rend\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'bite\':1},\'target\':\'normal\',\'type\':\'Water\',\'desc\':\'Power doubles if the user moves before the target.\',\'shortDesc\':\'Power doubles if user moves before the target.\'}"),
("fissure", "Fissure", "Ground", "Physical", 0, "30", 5, 0, "normal", "Deals damage to the target equal to the target\'s maximum HP. Ignores accuracy and evasiveness modifiers. This attack\'s accuracy is equal to (user\'s level - target\'s level + 30)%, and fails if the target is at a higher level. Pokemon with the Sturdy Ability are immune.", "OHKOs the target. Fails if user is a lower level.", "{\'protect\':1,\'mirror\':1,\'nonsky\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':90,\'accuracy\':30,\'basePower\':0,\'category\':\'Physical\',\'name\':\'Fissure\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'nonsky\':1,\'metronome\':1},\'ohko\':true,\'target\':\'normal\',\'type\':\'Ground\',\'zMove\':{\'basePower\':180},\'maxMove\':{\'basePower\':130},\'contestType\':\'Tough\',\'desc\':\'Deals damage to the target equal to the target\'s maximum HP. Ignores accuracy and evasiveness modifiers. This attack\'s accuracy is equal to (user\'s level - target\'s level + 30)%, and fails if the target is at a higher level. Pokemon with the Sturdy Ability are immune.\',\'shortDesc\':\'OHKOs the target. Fails if user is a lower level.\'}"),
("flail", "Flail", "Normal", "Physical", 0, "100", 15, 0, "normal", "The power of this move is 20 if X is 33 to 48, 40 if X is 17 to 32, 80 if X is 10 to 16, 100 if X is 5 to 9, 150 if X is 2 to 4, and 200 if X is 0 or 1, where X is equal to (user\'s current HP * 48 / user\'s maximum HP), rounded down.", "More power the less HP the user has left.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':175,\'accuracy\':100,\'basePower\':0,\'basePowerCallback\':true,\'category\':\'Physical\',\'name\':\'Flail\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'basePower\':160},\'maxMove\':{\'basePower\':130},\'contestType\':\'Cute\',\'desc\':\'The power of this move is 20 if X is 33 to 48, 40 if X is 17 to 32, 80 if X is 10 to 16, 100 if X is 5 to 9, 150 if X is 2 to 4, and 200 if X is 0 or 1, where X is equal to (user\'s current HP * 48 \\/ user\'s maximum HP), rounded down.\',\'shortDesc\':\'More power the less HP the user has left.\'}"),
("flameburst", "Flame Burst", "Fire", "Special", 70, "100", 15, 0, "normal", "If this move is successful, the target\'s ally loses 1/16 of its maximum HP, rounded down, unless it has the Magic Guard Ability.", "Damages Pokemon next to the target as well.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':481,\'accuracy\':100,\'basePower\':70,\'category\':\'Special\',\'isNonstandard\':\'Past\',\'name\':\'Flame Burst\',\'pp\':15,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Fire\',\'contestType\':\'Beautiful\',\'desc\':\'If this move is successful, the target\'s ally loses 1\\/16 of its maximum HP, rounded down, unless it has the Magic Guard Ability.\',\'shortDesc\':\'Damages Pokemon next to the target as well.\'}"),
