INSERT INTO `api_moves` (`id`, `name`, `type`, `category`, `basePower`, `accuracy`, `pp`, `priority`, `target`, `desc`, `shortDesc`, `flags`, `secondary`, `secondaries`, `drain`, `boosts`, `self`, `selfBoost`, `condition`, `volatileStatus`, `status`, `weather`, `terrain`, `pseudoWeather`, `heal`, `recoil`, `multihit`, `raw_json`) VALUES
("matblock", "Mat Block", "Fighting", "Status", 0, "1", 10, 0, "allySide", "The user and its party members are protected from damaging attacks made by other Pokemon, including allies, during this turn. Fails unless it is the user\'s first turn on the field, if the user moves last this turn, or if this move is already in effect for the user\'s side.", "Protects allies from damaging attacks. Turn 1 only.", "{\'snatch\':1,\'nonsky\':1,\'noassist\':1,\'failcopycat\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1,\'onTryHitPriority\':3}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':561,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Mat Block\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1,\'nonsky\':1,\'noassist\':1,\'failcopycat\':1},\'stallingMove\':true,\'sideCondition\':\'matblock\',\'condition\':{\'duration\':1,\'onTryHitPriority\':3},\'target\':\'allySide\',\'type\':\'Fighting\',\'zMove\':{\'boost\':{\'def\':1}},\'contestType\':\'Cool\',\'desc\':\'The user and its party members are protected from damaging attacks made by other Pokemon, including allies, during this turn. Fails unless it is the user\'s first turn on the field, if the user moves last this turn, or if this move is already in effect for the user\'s side.\',\'shortDesc\':\'Protects allies from damaging attacks. Turn 1 only.\'}"),
("matchagotcha", "Matcha Gotcha", "Grass", "Special", 80, "90", 15, 0, "allAdjacentFoes", "Has a 20% chance to burn the target. The user recovers 1/2 the HP lost by the target, rounded half up. If Big Root is held by the user, the HP recovered is 1.3x normal, rounded half down. The target thaws out if it is frozen.", "20% burn. Recovers 50% dmg dealt. Thaws foe(s).", "{\'protect\':1,\'mirror\':1,\'defrost\':1,\'heal\':1,\'metronome\':1}", "{\'chance\':20,\'status\':\'brn\'}", NULL, "[1,2]", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':902,\'accuracy\':90,\'basePower\':80,\'category\':\'Special\',\'name\':\'Matcha Gotcha\',\'pp\':15,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'defrost\':1,\'heal\':1,\'metronome\':1},\'drain\':[1,2],\'thawsTarget\':true,\'secondary\':{\'chance\':20,\'status\':\'brn\'},\'target\':\'allAdjacentFoes\',\'type\':\'Grass\',\'desc\':\'Has a 20% chance to burn the target. The user recovers 1\\/2 the HP lost by the target, rounded half up. If Big Root is held by the user, the HP recovered is 1.3x normal, rounded half down. The target thaws out if it is frozen.\',\'shortDesc\':\'20% burn. Recovers 50% dmg dealt. Thaws foe(s).\'}"),
("maxairstream", "Max Airstream", "Flying", "Physical", 10, "1", 10, 0, "adjacentFoe", "Power is equal to the base move\'s Max Move power. If this move is successful, the Speed of each Pokemon on the user\'s side is raised by 1 stage, even if they have a substitute. This effect does not happen if the user is not Dynamaxed. If this move is used as a base move, it deals damage with a power of 0.", "Base move affects power. Allies: +1 Speed.", "[]", NULL, NULL, NULL, NULL, "[]", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':766,\'accuracy\':true,\'basePower\':10,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Max Airstream\',\'pp\':10,\'priority\':0,\'flags\':[],\'isMax\':true,\'self\':[],\'target\':\'adjacentFoe\',\'type\':\'Flying\',\'contestType\':\'Cool\',\'desc\':\'Power is equal to the base move\'s Max Move power. If this move is successful, the Speed of each Pokemon on the user\'s side is raised by 1 stage, even if they have a substitute. This effect does not happen if the user is not Dynamaxed. If this move is used as a base move, it deals damage with a power of 0.\',\'shortDesc\':\'Base move affects power. Allies: +1 Speed.\'}"),
