("mightycleave", "Mighty Cleave", "Rock", "Physical", 95, "100", 5, 0, "normal", "Bypasses protection without breaking it.", "Bypasses protection without breaking it.", "{\'contact\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':910,\'accuracy\':100,\'basePower\':95,\'category\':\'Physical\',\'name\':\'Mighty Cleave\',\'pp\':5,\'priority\':0,\'flags\':{\'contact\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1},\'target\':\'normal\',\'type\':\'Rock\',\'desc\':\'Bypasses protection without breaking it.\',\'shortDesc\':\'Bypasses protection without breaking it.\'}"),
("milkdrink", "Milk Drink", "Normal", "Status", 0, "1", 5, 0, "self", "The user restores 1/2 of its maximum HP, rounded half up.", "Heals the user by 50% of its max HP.", "{\'snatch\':1,\'heal\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "[1,2]", NULL, NULL, "{\'num\':208,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Milk Drink\',\'pp\':5,\'priority\':0,\'flags\':{\'snatch\':1,\'heal\':1,\'metronome\':1},\'heal\':[1,2],\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Cute\',\'desc\':\'The user restores 1\\/2 of its maximum HP, rounded half up.\',\'shortDesc\':\'Heals the user by 50% of its max HP.\'}"),
("mimic", "Mimic", "Normal", "Status", 0, "1", 10, 0, "normal", "While the user remains active, this move is replaced by the last move used by the target. The copied move has the maximum PP for that move. Fails if the target has not made a move, if the user has Transformed, if the user already knows the move, or if the move is Assist, Behemoth Bash, Behemoth Blade, Belch, Blazing Torque, Celebrate, Chatter, Combat Torque, Copycat, Dynamax Cannon, Hold Hands, Magical Torque, Me First, Metronome, Mimic, Mirror Move, Nature Power, Noxious Torque, Sketch, Sleep Talk, Struggle, Tera Starstorm, Transform, or Wicked Torque.", "The last move the target used replaces this one.", "{\'protect\':1,\'bypasssub\':1,\'allyanim\':1,\'failencore\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failmimic\':1,\'failinstruct\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':102,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Mimic\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'bypasssub\':1,\'allyanim\':1,\'failencore\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failmimic\':1,\'failinstruct\':1},\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'boost\':{\'accuracy\':1}},\'contestType\':\'Cute\',\'desc\':\'While the user remains active, this move is replaced by the last move used by the target. The copied move has the maximum PP for that move. Fails if the target has not made a move, if the user has Transformed, if the user already knows the move, or if the move is Assist, Behemoth Bash, Behemoth Blade, Belch, Blazing Torque, Celebrate, Chatter, Combat Torque, Copycat, Dynamax Cannon, Hold Hands, Magical Torque, Me First, Metronome, Mimic, Mirror Move, Nature Power, Noxious Torque, Sketch, Sleep Talk, Struggle, Tera Starstorm, Transform, or Wicked Torque.\',\'shortDesc\':\'The last move the target used replaces this one.\'}"),
("mindblown", "Mind Blown", "Fire", "Special", 150, "100", 5, 0, "allAdjacent", "Whether or not this move is successful and even if it would cause fainting, the user loses 1/2 of its maximum HP, rounded up, unless the user has the Magic Guard Ability. This move is prevented from executing and the user does not lose HP if any active Pokemon has the Damp Ability, or if this move is Fire type and the user is affected by Powder or the weather is Primordial Sea.", "User loses 50% max HP. Hits adjacent Pokemon.", "{\'protect\':1,\'mirror\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':720,\'accuracy\':100,\'basePower\':150,\'category\':\'Special\',\'isNonstandard\':\'Past\',\'name\':\'Mind Blown\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1},\'mindBlownRecoil\':true,\'target\':\'allAdjacent\',\'type\':\'Fire\',\'contestType\':\'Cool\',\'desc\':\'Whether or not this move is successful and even if it would cause fainting, the user loses 1\\/2 of its maximum HP, rounded up, unless the user has the Magic Guard Ability. This move is prevented from executing and the user does not lose HP if any active Pokemon has the Damp Ability, or if this move is Fire type and the user is affected by Powder or the weather is Primordial Sea.\',\'shortDesc\':\'User loses 50% max HP. Hits adjacent Pokemon.\'}"),
("mindreader", "Mind Reader", "Normal", "Status", 0, "1", 5, 0, "normal", "Until the end of the next turn, the target cannot avoid the user\'s moves, even if the target is in the middle of a two-turn move. The effect ends if either the user or the target leaves the field. Fails if this effect is active for the user.", "User\'s next move will not miss the target.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':170,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Mind Reader\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'boost\':{\'spa\':1}},\'contestType\':\'Clever\',\'desc\':\'Until the end of the next turn, the target cannot avoid the user\'s moves, even if the target is in the middle of a two-turn move. The effect ends if either the user or the target leaves the field. Fails if this effect is active for the user.\',\'shortDesc\':\'User\'s next move will not miss the target.\'}");
INSERT INTO `api_moves` (`id`, `name`, `type`, `category`, `basePower`, `accuracy`, `pp`, `priority`, `target`, `desc`, `shortDesc`, `flags`, `secondary`, `secondaries`, `drain`, `boosts`, `self`, `selfBoost`, `condition`, `volatileStatus`, `status`, `weather`, `terrain`, `pseudoWeather`, `heal`, `recoil`, `multihit`, `raw_json`) VALUES
("minimize", "Minimize", "Normal", "Status", 0, "1", 10, 0, "self", "Raises the user\'s evasiveness by 2 stages. Whether or not the user\'s evasiveness was changed, Body Slam, Dragon Rush, Flying Press, Heat Crash, Heavy Slam, Malicious Moonsault, Steamroller, Stomp, and Supercell Slam will not check accuracy and have their damage doubled if used against the user while it is active.", "Raises the user\'s evasiveness by 2.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, "{\'evasion\':2}", NULL, NULL, "{\'noCopy\':true}", "minimize", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':107,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Minimize\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'volatileStatus\':\'minimize\',\'condition\':{\'noCopy\':true},\'boosts\':{\'evasion\':2},\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Cute\',\'desc\':\'Raises the user\'s evasiveness by 2 stages. Whether or not the user\'s evasiveness was changed, Body Slam, Dragon Rush, Flying Press, Heat Crash, Heavy Slam, Malicious Moonsault, Steamroller, Stomp, and Supercell Slam will not check accuracy and have their damage doubled if used against the user while it is active.\',\'shortDesc\':\'Raises the user\'s evasiveness by 2.\'}"),
("miracleeye", "Miracle Eye", "Psychic", "Status", 0, "1", 40, 0, "normal", "As long as the target remains active, its evasiveness stat stage is ignored during accuracy checks against it if it is greater than 0, and Psychic-type attacks can hit the target if it is a Dark type. Fails if the target is already affected, or affected by Foresight or Odor Sleuth.", "Psychic hits Dark. Evasiveness ignored.", "{\'protect\':1,\'reflectable\':1,\'mirror\':1,\'bypasssub\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'noCopy\':true}", "miracleeye", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':357,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Miracle Eye\',\'pp\':40,\'priority\':0,\'flags\':{\'protect\':1,\'reflectable\':1,\'mirror\':1,\'bypasssub\':1,\'metronome\':1},\'volatileStatus\':\'miracleeye\',\'condition\':{\'noCopy\':true},\'target\':\'normal\',\'type\':\'Psychic\',\'zMove\':{\'boost\':{\'spa\':1}},\'contestType\':\'Clever\',\'desc\':\'As long as the target remains active, its evasiveness stat stage is ignored during accuracy checks against it if it is greater than 0, and Psychic-type attacks can hit the target if it is a Dark type. Fails if the target is already affected, or affected by Foresight or Odor Sleuth.\',\'shortDesc\':\'Psychic hits Dark. Evasiveness ignored.\'}"),
("mirrorcoat", "Mirror Coat", "Psychic", "Special", 0, "100", 20, -5, "scripted", "Deals damage to the last opposing Pokemon to hit the user with a special attack this turn equal to twice the HP lost by the user from that attack. If the user did not lose HP from the attack, this move deals 1 HP of damage instead. If that opposing Pokemon\'s position is no longer in use and there is another opposing Pokemon on the field, the damage is done to it instead. Only the last hit of a multi-hit attack is counted. Fails if the user was not hit by an opposing Pokemon\'s special attack this turn.", "If hit by special attack, returns double damage.", "{\'protect\':1,\'failmefirst\':1,\'noassist\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1,\'noCopy\':true,\'onRedirectTargetPriority\':-1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':243,\'accuracy\':100,\'basePower\':0,\'category\':\'Special\',\'name\':\'Mirror Coat\',\'pp\':20,\'priority\':-5,\'flags\':{\'protect\':1,\'failmefirst\':1,\'noassist\':1},\'condition\':{\'duration\':1,\'noCopy\':true,\'onRedirectTargetPriority\':-1},\'target\':\'scripted\',\'type\':\'Psychic\',\'contestType\':\'Beautiful\',\'desc\':\'Deals damage to the last opposing Pokemon to hit the user with a special attack this turn equal to twice the HP lost by the user from that attack. If the user did not lose HP from the attack, this move deals 1 HP of damage instead. If that opposing Pokemon\'s position is no longer in use and there is another opposing Pokemon on the field, the damage is done to it instead. Only the last hit of a multi-hit attack is counted. Fails if the user was not hit by an opposing Pokemon\'s special attack this turn.\',\'shortDesc\':\'If hit by special attack, returns double damage.\'}"),
("mirrormove", "Mirror Move", "Flying", "Status", 0, "1", 20, 0, "normal", "The user uses the last move used by the target. The copied move is used against that target, if possible. Fails if the target has not made a move, or if the last move used cannot be copied by this move.", "User uses the target\'s last used move against it.", "{\'failencore\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failmimic\':1,\'failinstruct\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':119,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Mirror Move\',\'pp\':20,\'priority\':0,\'flags\':{\'failencore\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failmimic\':1,\'failinstruct\':1},\'callsMove\':true,\'target\':\'normal\',\'type\':\'Flying\',\'zMove\':{\'boost\':{\'atk\':2}},\'contestType\':\'Clever\',\'desc\':\'The user uses the last move used by the target. The copied move is used against that target, if possible. Fails if the target has not made a move, or if the last move used cannot be copied by this move.\',\'shortDesc\':\'User uses the target\'s last used move against it.\'}"),
("mirrorshot", "Mirror Shot", "Steel", "Special", 65, "85", 10, 0, "normal", "Has a 30% chance to lower the target\'s accuracy by 1 stage.", "30% chance to lower the target\'s accuracy by 1.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':30,\'boosts\':{\'accuracy\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':429,\'accuracy\':85,\'basePower\':65,\'category\':\'Special\',\'isNonstandard\':\'Past\',\'name\':\'Mirror Shot\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':30,\'boosts\':{\'accuracy\':-1}},\'target\':\'normal\',\'type\':\'Steel\',\'contestType\':\'Beautiful\',\'desc\':\'Has a 30% chance to lower the target\'s accuracy by 1 stage.\',\'shortDesc\':\'30% chance to lower the target\'s accuracy by 1.\'}"),
("mist", "Mist", "Ice", "Status", 0, "1", 30, 0, "allySide", "For 5 turns, the user and its party members are protected from having their stat stages lowered by other Pokemon. Fails if the effect is already active on the user\'s side.", "For 5 turns, protects user\'s party from stat drops.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':5,\'onSideResidualOrder\':26,\'onSideResidualSubOrder\':4}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':54,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Mist\',\'pp\':30,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'sideCondition\':\'mist\',\'condition\':{\'duration\':5,\'onSideResidualOrder\':26,\'onSideResidualSubOrder\':4},\'target\':\'allySide\',\'type\':\'Ice\',\'zMove\':{\'effect\':\'heal\'},\'contestType\':\'Beautiful\',\'desc\':\'For 5 turns, the user and its party members are protected from having their stat stages lowered by other Pokemon. Fails if the effect is already active on the user\'s side.\',\'shortDesc\':\'For 5 turns, protects user\'s party from stat drops.\'}"),
("mistball", "Mist Ball", "Psychic", "Special", 95, "100", 5, 0, "normal", "Has a 50% chance to lower the target\'s Special Attack by 1 stage.", "50% chance to lower the target\'s Sp. Atk by 1.", "{\'protect\':1,\'mirror\':1,\'metronome\':1,\'bullet\':1}", "{\'chance\':50,\'boosts\':{\'spa\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':296,\'accuracy\':100,\'basePower\':95,\'category\':\'Special\',\'name\':\'Mist Ball\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1,\'bullet\':1},\'secondary\':{\'chance\':50,\'boosts\':{\'spa\':-1}},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Clever\',\'desc\':\'Has a 50% chance to lower the target\'s Special Attack by 1 stage.\',\'shortDesc\':\'50% chance to lower the target\'s Sp. Atk by 1.\'}"),
("mistyexplosion", "Misty Explosion", "Fairy", "Special", 100, "100", 5, 0, "allAdjacent", "If the current terrain is Misty Terrain and the user is grounded, this move\'s power is multiplied by 1.5. The user faints after using this move, even if this move fails for having no target. This move is prevented from executing if any active Pokemon has the Damp Ability.", "User faints. User on Misty Terrain: 1.5x power.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':802,\'accuracy\':100,\'basePower\':100,\'category\':\'Special\',\'name\':\'Misty Explosion\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'selfdestruct\':\'always\',\'target\':\'allAdjacent\',\'type\':\'Fairy\',\'desc\':\'If the current terrain is Misty Terrain and the user is grounded, this move\'s power is multiplied by 1.5. The user faints after using this move, even if this move fails for having no target. This move is prevented from executing if any active Pokemon has the Damp Ability.\',\'shortDesc\':\'User faints. User on Misty Terrain: 1.5x power.\'}"),
("mistyterrain", "Misty Terrain", "Fairy", "Status", 0, "1", 10, 0, "all", "For 5 turns, the terrain becomes Misty Terrain. During the effect, the power of Dragon-type attacks used against grounded Pokemon is multiplied by 0.5 and grounded Pokemon cannot be inflicted with a non-volatile status condition nor confusion. Grounded Pokemon can become affected by Yawn but cannot fall asleep from its effect. Camouflage transforms the user into a Fairy type, Nature Power becomes Moonblast, and Secret Power has a 30% chance to lower Special Attack by 1 stage. Fails if the current terrain is Misty Terrain.", "5 turns. Can\'t status,-Dragon power vs grounded.", "{\'nonsky\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'effectType\':\'Terrain\',\'duration\':5,\'onBasePowerPriority\':6,\'onFieldResidualOrder\':27,\'onFieldResidualSubOrder\':7}", NULL, NULL, NULL, "mistyterrain", NULL, NULL, NULL, NULL, "{\'num\':581,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Misty Terrain\',\'pp\':10,\'priority\':0,\'flags\':{\'nonsky\':1,\'metronome\':1},\'terrain\':\'mistyterrain\',\'condition\':{\'effectType\':\'Terrain\',\'duration\':5,\'onBasePowerPriority\':6,\'onFieldResidualOrder\':27,\'onFieldResidualSubOrder\':7},\'target\':\'all\',\'type\':\'Fairy\',\'zMove\':{\'boost\':{\'spd\':1}},\'contestType\':\'Beautiful\',\'desc\':\'For 5 turns, the terrain becomes Misty Terrain. During the effect, the power of Dragon-type attacks used against grounded Pokemon is multiplied by 0.5 and grounded Pokemon cannot be inflicted with a non-volatile status condition nor confusion. Grounded Pokemon can become affected by Yawn but cannot fall asleep from its effect. Camouflage transforms the user into a Fairy type, Nature Power becomes Moonblast, and Secret Power has a 30% chance to lower Special Attack by 1 stage. Fails if the current terrain is Misty Terrain.\',\'shortDesc\':\'5 turns. Can\'t status,-Dragon power vs grounded.\'}"),
