("protect", "Protect", "Normal", "Status", 0, "1", 10, 4, "self", "The user is protected from most attacks made by other Pokemon during this turn. This move has a 1/X chance of being successful, where X starts at 1 and triples each time this move is successfully used. X resets to 1 if this move fails, if the user\'s last move used is not Baneful Bunker, Burning Bulwark, Detect, Endure, King\'s Shield, Max Guard, Obstruct, Protect, Quick Guard, Silk Trap, Spiky Shield, or Wide Guard, or if it was one of those moves and the user\'s protection was broken. Fails if the user moves last this turn.", "Prevents moves from affecting the user this turn.", "{\'noassist\':1,\'failcopycat\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1,\'onTryHitPriority\':3}", "protect", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':182,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Protect\',\'pp\':10,\'priority\':4,\'flags\':{\'noassist\':1,\'failcopycat\':1},\'stallingMove\':true,\'volatileStatus\':\'protect\',\'condition\':{\'duration\':1,\'onTryHitPriority\':3},\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Cute\',\'desc\':\'The user is protected from most attacks made by other Pokemon during this turn. This move has a 1\\/X chance of being successful, where X starts at 1 and triples each time this move is successfully used. X resets to 1 if this move fails, if the user\'s last move used is not Baneful Bunker, Burning Bulwark, Detect, Endure, King\'s Shield, Max Guard, Obstruct, Protect, Quick Guard, Silk Trap, Spiky Shield, or Wide Guard, or if it was one of those moves and the user\'s protection was broken. Fails if the user moves last this turn.\',\'shortDesc\':\'Prevents moves from affecting the user this turn.\'}"),
("psybeam", "Psybeam", "Psychic", "Special", 65, "100", 20, 0, "normal", "Has a 10% chance to confuse the target.", "10% chance to confuse the target.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':10,\'volatileStatus\':\'confusion\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':60,\'accuracy\':100,\'basePower\':65,\'category\':\'Special\',\'name\':\'Psybeam\',\'pp\':20,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':10,\'volatileStatus\':\'confusion\'},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Beautiful\',\'desc\':\'Has a 10% chance to confuse the target.\',\'shortDesc\':\'10% chance to confuse the target.\'}"),
("psyblade", "Psyblade", "Psychic", "Physical", 80, "100", 15, 0, "normal", "If the current terrain is Electric Terrain, this move\'s power is multiplied by 1.5.", "During Electric Terrain: 1.5x power.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':875,\'accuracy\':100,\'basePower\':80,\'category\':\'Physical\',\'name\':\'Psyblade\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1},\'target\':\'normal\',\'type\':\'Psychic\',\'desc\':\'If the current terrain is Electric Terrain, this move\'s power is multiplied by 1.5.\',\'shortDesc\':\'During Electric Terrain: 1.5x power.\'}"),
("psychic", "Psychic", "Psychic", "Special", 90, "100", 10, 0, "normal", "Has a 10% chance to lower the target\'s Special Defense by 1 stage.", "10% chance to lower the target\'s Sp. Def by 1.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':10,\'boosts\':{\'spd\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':94,\'accuracy\':100,\'basePower\':90,\'category\':\'Special\',\'name\':\'Psychic\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':10,\'boosts\':{\'spd\':-1}},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Clever\',\'desc\':\'Has a 10% chance to lower the target\'s Special Defense by 1 stage.\',\'shortDesc\':\'10% chance to lower the target\'s Sp. Def by 1.\'}");
INSERT INTO `api_moves` (`id`, `name`, `type`, `category`, `basePower`, `accuracy`, `pp`, `priority`, `target`, `desc`, `shortDesc`, `flags`, `secondary`, `secondaries`, `drain`, `boosts`, `self`, `selfBoost`, `condition`, `volatileStatus`, `status`, `weather`, `terrain`, `pseudoWeather`, `heal`, `recoil`, `multihit`, `raw_json`) VALUES
("psychicfangs", "Psychic Fangs", "Psychic", "Physical", 85, "100", 10, 0, "normal", "If this attack does not miss, the effects of Reflect, Light Screen, and Aurora Veil end for the target\'s side of the field before damage is calculated.", "Destroys screens, unless the target is immune.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'bite\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':706,\'accuracy\':100,\'basePower\':85,\'category\':\'Physical\',\'name\':\'Psychic Fangs\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'bite\':1},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Clever\',\'desc\':\'If this attack does not miss, the effects of Reflect, Light Screen, and Aurora Veil end for the target\'s side of the field before damage is calculated.\',\'shortDesc\':\'Destroys screens, unless the target is immune.\'}"),
("psychicnoise", "Psychic Noise", "Psychic", "Special", 75, "100", 10, 0, "normal", "For 2 turns, the target is prevented from restoring any HP as long as it remains active. During the effect, healing and draining moves are unusable, and Abilities and items that grant healing will not heal the user. If an affected Pokemon uses Baton Pass, the replacement will remain unable to restore its HP. Pain Split and the Regenerator Ability are unaffected.", "For 2 turns, the target is prevented from healing.", "{\'protect\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1,\'metronome\':1}", "{\'chance\':100,\'volatileStatus\':\'healblock\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':917,\'accuracy\':100,\'basePower\':75,\'category\':\'Special\',\'name\':\'Psychic Noise\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1,\'metronome\':1},\'secondary\':{\'chance\':100,\'volatileStatus\':\'healblock\'},\'target\':\'normal\',\'type\':\'Psychic\',\'desc\':\'For 2 turns, the target is prevented from restoring any HP as long as it remains active. During the effect, healing and draining moves are unusable, and Abilities and items that grant healing will not heal the user. If an affected Pokemon uses Baton Pass, the replacement will remain unable to restore its HP. Pain Split and the Regenerator Ability are unaffected.\',\'shortDesc\':\'For 2 turns, the target is prevented from healing.\'}"),
("psychicterrain", "Psychic Terrain", "Psychic", "Status", 0, "1", 10, 0, "all", "For 5 turns, the terrain becomes Psychic Terrain. During the effect, the power of Psychic-type attacks made by grounded Pokemon is multiplied by 1.3 and grounded Pokemon cannot be hit by moves with priority greater than 0, unless the target is an ally. Camouflage transforms the user into a Psychic type, Nature Power becomes Psychic, and Secret Power has a 30% chance to lower the target\'s Speed by 1 stage. Fails if the current terrain is Psychic Terrain.", "5 turns. Grounded: +Psychic power, priority-safe.", "{\'nonsky\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'effectType\':\'Terrain\',\'duration\':5,\'onTryHitPriority\':4,\'onBasePowerPriority\':6,\'onFieldResidualOrder\':27,\'onFieldResidualSubOrder\':7}", NULL, NULL, NULL, "psychicterrain", NULL, NULL, NULL, NULL, "{\'num\':678,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Psychic Terrain\',\'pp\':10,\'priority\':0,\'flags\':{\'nonsky\':1,\'metronome\':1},\'terrain\':\'psychicterrain\',\'condition\':{\'effectType\':\'Terrain\',\'duration\':5,\'onTryHitPriority\':4,\'onBasePowerPriority\':6,\'onFieldResidualOrder\':27,\'onFieldResidualSubOrder\':7},\'target\':\'all\',\'type\':\'Psychic\',\'zMove\':{\'boost\':{\'spa\':1}},\'contestType\':\'Clever\',\'desc\':\'For 5 turns, the terrain becomes Psychic Terrain. During the effect, the power of Psychic-type attacks made by grounded Pokemon is multiplied by 1.3 and grounded Pokemon cannot be hit by moves with priority greater than 0, unless the target is an ally. Camouflage transforms the user into a Psychic type, Nature Power becomes Psychic, and Secret Power has a 30% chance to lower the target\'s Speed by 1 stage. Fails if the current terrain is Psychic Terrain.\',\'shortDesc\':\'5 turns. Grounded: +Psychic power, priority-safe.\'}"),
("psychoboost", "Psycho Boost", "Psychic", "Special", 140, "90", 5, 0, "normal", "Lowers the user\'s Special Attack by 2 stages.", "Lowers the user\'s Sp. Atk by 2.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, "{\'boosts\':{\'spa\':-2}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':354,\'accuracy\':90,\'basePower\':140,\'category\':\'Special\',\'name\':\'Psycho Boost\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'self\':{\'boosts\':{\'spa\':-2}},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Clever\',\'desc\':\'Lowers the user\'s Special Attack by 2 stages.\',\'shortDesc\':\'Lowers the user\'s Sp. Atk by 2.\'}"),
("psychocut", "Psycho Cut", "Psychic", "Physical", 70, "100", 20, 0, "normal", "Has a higher chance for a critical hit.", "High critical hit ratio.", "{\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':427,\'accuracy\':100,\'basePower\':70,\'category\':\'Physical\',\'name\':\'Psycho Cut\',\'pp\':20,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1},\'critRatio\':2,\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Cool\',\'desc\':\'Has a higher chance for a critical hit.\',\'shortDesc\':\'High critical hit ratio.\'}"),
("psychoshift", "Psycho Shift", "Psychic", "Status", 0, "100", 10, 0, "normal", "The user\'s non-volatile status condition is transferred to the target, and the user is then cured. Fails if the user has no non-volatile status condition or if the target already has one.", "Transfers the user\'s status ailment to the target.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, "[]", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':375,\'accuracy\':100,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Psycho Shift\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'self\':[],\'target\':\'normal\',\'type\':\'Psychic\',\'zMove\':{\'boost\':{\'spa\':2}},\'contestType\':\'Clever\',\'desc\':\'The user\'s non-volatile status condition is transferred to the target, and the user is then cured. Fails if the user has no non-volatile status condition or if the target already has one.\',\'shortDesc\':\'Transfers the user\'s status ailment to the target.\'}"),
("psychup", "Psych Up", "Normal", "Status", 0, "1", 10, 0, "normal", "The user copies all of the target\'s current stat stage changes.", "Copies the target\'s current stat stages.", "{\'bypasssub\':1,\'allyanim\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':244,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Psych Up\',\'pp\':10,\'priority\':0,\'flags\':{\'bypasssub\':1,\'allyanim\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'heal\'},\'contestType\':\'Clever\',\'desc\':\'The user copies all of the target\'s current stat stage changes.\',\'shortDesc\':\'Copies the target\'s current stat stages.\'}"),
("psyshieldbash", "Psyshield Bash", "Psychic", "Physical", 70, "90", 10, 0, "normal", "Has a 100% chance to raise the user\'s Defense by 1 stage.", "100% chance to raise the user\'s Defense by 1.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':100,\'self\':{\'boosts\':{\'def\':1}}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':828,\'accuracy\':90,\'basePower\':70,\'category\':\'Physical\',\'name\':\'Psyshield Bash\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':100,\'self\':{\'boosts\':{\'def\':1}}},\'target\':\'normal\',\'type\':\'Psychic\',\'desc\':\'Has a 100% chance to raise the user\'s Defense by 1 stage.\',\'shortDesc\':\'100% chance to raise the user\'s Defense by 1.\'}"),
("psyshock", "Psyshock", "Psychic", "Special", 80, "100", 10, 0, "normal", "Deals damage to the target based on its Defense instead of Special Defense.", "Damages target based on Defense, not Sp. Def.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':473,\'accuracy\':100,\'basePower\':80,\'category\':\'Special\',\'overrideDefensiveStat\':\'def\',\'name\':\'Psyshock\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Beautiful\',\'desc\':\'Deals damage to the target based on its Defense instead of Special Defense.\',\'shortDesc\':\'Damages target based on Defense, not Sp. Def.\'}"),
("psystrike", "Psystrike", "Psychic", "Special", 100, "100", 10, 0, "normal", "Deals damage to the target based on its Defense instead of Special Defense.", "Damages target based on Defense, not Sp. Def.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':540,\'accuracy\':100,\'basePower\':100,\'category\':\'Special\',\'overrideDefensiveStat\':\'def\',\'name\':\'Psystrike\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Cool\',\'desc\':\'Deals damage to the target based on its Defense instead of Special Defense.\',\'shortDesc\':\'Damages target based on Defense, not Sp. Def.\'}"),
("psywave", "Psywave", "Psychic", "Special", 0, "100", 15, 0, "normal", "Deals damage to the target equal to (user\'s level) * (X + 50) / 100, where X is a random number from 0 to 100, rounded down, but not less than 1 HP.", "Random damage equal to 0.5x-1.5x user\'s level.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':149,\'accuracy\':100,\'basePower\':0,\'category\':\'Special\',\'isNonstandard\':\'Past\',\'name\':\'Psywave\',\'pp\':15,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Clever\',\'desc\':\'Deals damage to the target equal to (user\'s level) * (X + 50) \\/ 100, where X is a random number from 0 to 100, rounded down, but not less than 1 HP.\',\'shortDesc\':\'Random damage equal to 0.5x-1.5x user\'s level.\'}"),
("pulverizingpancake", "Pulverizing Pancake", "Normal", "Physical", 210, "1", 1, 0, "normal", "No additional effect.", "No additional effect.", "{\'contact\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':701,\'accuracy\':true,\'basePower\':210,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Pulverizing Pancake\',\'pp\':1,\'priority\':0,\'flags\':{\'contact\':1},\'isZ\':\'snorliumz\',\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Cool\',\'desc\':\'No additional effect.\',\'shortDesc\':\'No additional effect.\'}"),
("punishment", "Punishment", "Dark", "Physical", 0, "100", 5, 0, "normal", "Power is equal to 60+(X*20), where X is the target\'s total stat stage changes that are greater than 0, but not more than 200 power.", "60 power +20 for each of the target\'s stat boosts.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':386,\'accuracy\':100,\'basePower\':0,\'basePowerCallback\':true,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Punishment\',\'pp\':5,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Dark\',\'zMove\':{\'basePower\':160},\'maxMove\':{\'basePower\':130},\'contestType\':\'Cool\',\'desc\':\'Power is equal to 60+(X*20), where X is the target\'s total stat stage changes that are greater than 0, but not more than 200 power.\',\'shortDesc\':\'60 power +20 for each of the target\'s stat boosts.\'}"),
("purify", "Purify", "Poison", "Status", 0, "1", 20, 0, "normal", "The target is cured if it has a non-volatile status condition. If the target was cured, the user restores 1/2 of its maximum HP, rounded down.", "Cures target\'s status; heals user 1/2 max HP if so.", "{\'protect\':1,\'reflectable\':1,\'heal\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':685,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Purify\',\'pp\':20,\'priority\':0,\'flags\':{\'protect\':1,\'reflectable\':1,\'heal\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Poison\',\'zMove\':{\'boost\':{\'atk\':1,\'def\':1,\'spa\':1,\'spd\':1,\'spe\':1}},\'contestType\':\'Beautiful\',\'desc\':\'The target is cured if it has a non-volatile status condition. If the target was cured, the user restores 1\\/2 of its maximum HP, rounded down.\',\'shortDesc\':\'Cures target\'s status; heals user 1\\/2 max HP if so.\'}"),
("pursuit", "Pursuit", "Dark", "Physical", 40, "100", 20, 0, "normal", "If an opposing Pokemon switches out this turn, this move hits that Pokemon before it leaves the field, even if it was not the original target. If the user moves after an opponent using Flip Turn, Parting Shot, Teleport, U-turn, or Volt Switch, but not Baton Pass, it will hit that opponent before it leaves the field. Power doubles and no accuracy check is done if the user hits an opponent switching out, and the user\'s turn is over; if an opponent faints from this, the replacement Pokemon does not become active until the end of the turn.", "If a foe is switching out, hits it at 2x power.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':228,\'accuracy\':100,\'basePower\':40,\'basePowerCallback\':true,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Pursuit\',\'pp\':20,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'condition\':{\'duration\':1},\'target\':\'normal\',\'type\':\'Dark\',\'contestType\':\'Clever\',\'desc\':\'If an opposing Pokemon switches out this turn, this move hits that Pokemon before it leaves the field, even if it was not the original target. If the user moves after an opponent using Flip Turn, Parting Shot, Teleport, U-turn, or Volt Switch, but not Baton Pass, it will hit that opponent before it leaves the field. Power doubles and no accuracy check is done if the user hits an opponent switching out, and the user\'s turn is over; if an opponent faints from this, the replacement Pokemon does not become active until the end of the turn.\',\'shortDesc\':\'If a foe is switching out, hits it at 2x power.\'}"),
("pyroball", "Pyro Ball", "Fire", "Physical", 120, "90", 5, 0, "normal", "Has a 10% chance to burn the target.", "10% chance to burn the target. Thaws user.", "{\'protect\':1,\'mirror\':1,\'defrost\':1,\'bullet\':1}", "{\'chance\':10,\'status\':\'brn\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':780,\'accuracy\':90,\'basePower\':120,\'category\':\'Physical\',\'name\':\'Pyro Ball\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'defrost\':1,\'bullet\':1},\'secondary\':{\'chance\':10,\'status\':\'brn\'},\'target\':\'normal\',\'type\':\'Fire\',\'desc\':\'Has a 10% chance to burn the target.\',\'shortDesc\':\'10% chance to burn the target. Thaws user.\'}"),
("quash", "Quash", "Dark", "Status", 0, "100", 15, 0, "normal", "Causes the target to take its turn after all other Pokemon this turn, no matter the priority of its selected move. Fails if the target already moved this turn.", "Forces the target to move last this turn.", "{\'protect\':1,\'mirror\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':511,\'accuracy\':100,\'basePower\':0,\'category\':\'Status\',\'name\':\'Quash\',\'pp\':15,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1},\'target\':\'normal\',\'type\':\'Dark\',\'zMove\':{\'boost\':{\'spe\':1}},\'contestType\':\'Clever\',\'desc\':\'Causes the target to take its turn after all other Pokemon this turn, no matter the priority of its selected move. Fails if the target already moved this turn.\',\'shortDesc\':\'Forces the target to move last this turn.\'}"),
("quickattack", "Quick Attack", "Normal", "Physical", 40, "100", 30, 1, "normal", "No additional effect.", "Usually goes first.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':98,\'accuracy\':100,\'basePower\':40,\'category\':\'Physical\',\'name\':\'Quick Attack\',\'pp\':30,\'priority\':1,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Cool\',\'desc\':\'No additional effect.\',\'shortDesc\':\'Usually goes first.\'}"),
("quickguard", "Quick Guard", "Fighting", "Status", 0, "1", 15, 3, "allySide", "The user and its party members are protected from attacks with original or altered priority greater than 0 made by other Pokemon, including allies, during this turn. This move modifies the same 1/X chance of being successful used by other protection moves, where X starts at 1 and triples each time this move is successfully used, but does not use the chance to check for failure. X resets to 1 if this move fails, if the user\'s last move used is not Baneful Bunker, Burning Bulwark, Detect, Endure, King\'s Shield, Max Guard, Obstruct, Protect, Quick Guard, Silk Trap, Spiky Shield, or Wide Guard, or if it was one of those moves and the user\'s protection was broken. Fails if the user moves last this turn or if this move is already in effect for the user\'s side.", "Protects allies from priority attacks this turn.", "{\'snatch\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1,\'onTryHitPriority\':4}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':501,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Quick Guard\',\'pp\':15,\'priority\':3,\'flags\':{\'snatch\':1},\'sideCondition\':\'quickguard\',\'condition\':{\'duration\':1,\'onTryHitPriority\':4},\'target\':\'allySide\',\'type\':\'Fighting\',\'zMove\':{\'boost\':{\'def\':1}},\'contestType\':\'Cool\',\'desc\':\'The user and its party members are protected from attacks with original or altered priority greater than 0 made by other Pokemon, including allies, during this turn. This move modifies the same 1\\/X chance of being successful used by other protection moves, where X starts at 1 and triples each time this move is successfully used, but does not use the chance to check for failure. X resets to 1 if this move fails, if the user\'s last move used is not Baneful Bunker, Burning Bulwark, Detect, Endure, King\'s Shield, Max Guard, Obstruct, Protect, Quick Guard, Silk Trap, Spiky Shield, or Wide Guard, or if it was one of those moves and the user\'s protection was broken. Fails if the user moves last this turn or if this move is already in effect for the user\'s side.\',\'shortDesc\':\'Protects allies from priority attacks this turn.\'}"),
("quiverdance", "Quiver Dance", "Bug", "Status", 0, "1", 20, 0, "self", "Raises the user\'s Special Attack, Special Defense, and Speed by 1 stage.", "Raises the user\'s Sp. Atk, Sp. Def, Speed by 1.", "{\'snatch\':1,\'dance\':1,\'metronome\':1}", NULL, NULL, NULL, "{\'spa\':1,\'spd\':1,\'spe\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':483,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Quiver Dance\',\'pp\':20,\'priority\':0,\'flags\':{\'snatch\':1,\'dance\':1,\'metronome\':1},\'boosts\':{\'spa\':1,\'spd\':1,\'spe\':1},\'target\':\'self\',\'type\':\'Bug\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Beautiful\',\'desc\':\'Raises the user\'s Special Attack, Special Defense, and Speed by 1 stage.\',\'shortDesc\':\'Raises the user\'s Sp. Atk, Sp. Def, Speed by 1.\'}"),
("rage", "Rage", "Normal", "Physical", 20, "100", 20, 0, "normal", "Once this move is successfully used, the user\'s Attack is raised by 1 stage every time it is hit by another Pokemon\'s attack as long as this move is chosen for use.", "Raises the user\'s Attack by 1 if hit during use.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, "{\'volatileStatus\':\'rage\'}", NULL, "{\'onBeforeMovePriority\':100}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':99,\'accuracy\':100,\'basePower\':20,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Rage\',\'pp\':20,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'self\':{\'volatileStatus\':\'rage\'},\'condition\':{\'onBeforeMovePriority\':100},\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Tough\',\'desc\':\'Once this move is successfully used, the user\'s Attack is raised by 1 stage every time it is hit by another Pokemon\'s attack as long as this move is chosen for use.\',\'shortDesc\':\'Raises the user\'s Attack by 1 if hit during use.\'}"),
("ragefist", "Rage Fist", "Ghost", "Physical", 50, "100", 10, 0, "normal", "Power is equal to 50+(X*50), where X is the total number of times the user has been hit by a damaging attack during the battle, even if the user did not lose HP from the attack. X cannot be greater than 6 and does not reset upon switching out or fainting. Each hit of a multi-hit attack is counted, but confusion damage is not counted.", "+50 power for each time user was hit. Max 6 hits.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'punch\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':889,\'accuracy\':100,\'basePower\':50,\'basePowerCallback\':true,\'category\':\'Physical\',\'name\':\'Rage Fist\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'punch\':1},\'target\':\'normal\',\'type\':\'Ghost\',\'desc\':\'Power is equal to 50+(X*50), where X is the total number of times the user has been hit by a damaging attack during the battle, even if the user did not lose HP from the attack. X cannot be greater than 6 and does not reset upon switching out or fainting. Each hit of a multi-hit attack is counted, but confusion damage is not counted.\',\'shortDesc\':\'+50 power for each time user was hit. Max 6 hits.\'}"),
("ragepowder", "Rage Powder", "Bug", "Status", 0, "1", 20, 2, "self", "Until the end of the turn, all single-target attacks from the opposing side are redirected to the user. Such attacks are redirected to the user before they can be reflected by Magic Coat or the Magic Bounce Ability, or drawn in by the Lightning Rod or Storm Drain Abilities. Fails if it is not a Double Battle or Battle Royal. This effect is ignored while the user is under the effect of Sky Drop.", "The foes\' moves target the user on the turn used.", "{\'noassist\':1,\'failcopycat\':1,\'powder\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1,\'onFoeRedirectTargetPriority\':1}", "ragepowder", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':476,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Rage Powder\',\'pp\':20,\'priority\':2,\'flags\':{\'noassist\':1,\'failcopycat\':1,\'powder\':1},\'volatileStatus\':\'ragepowder\',\'condition\':{\'duration\':1,\'onFoeRedirectTargetPriority\':1},\'target\':\'self\',\'type\':\'Bug\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Clever\',\'desc\':\'Until the end of the turn, all single-target attacks from the opposing side are redirected to the user. Such attacks are redirected to the user before they can be reflected by Magic Coat or the Magic Bounce Ability, or drawn in by the Lightning Rod or Storm Drain Abilities. Fails if it is not a Double Battle or Battle Royal. This effect is ignored while the user is under the effect of Sky Drop.\',\'shortDesc\':\'The foes\' moves target the user on the turn used.\'}"),
("ragingbull", "Raging Bull", "Normal", "Physical", 90, "100", 10, 0, "normal", "If this attack does not miss, the effects of Reflect, Light Screen, and Aurora Veil end for the target\'s side of the field before damage is calculated. If the user\'s current form is a Paldean Tauros, this move\'s type changes to match. Fighting type for Combat Breed, Fire type for Blaze Breed, and Water type for Aqua Breed.", "Destroys screens. Type depends on user\'s form.", "{\'contact\':1,\'protect\':1,\'mirror\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':873,\'accuracy\':100,\'basePower\':90,\'category\':\'Physical\',\'name\':\'Raging Bull\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1},\'target\':\'normal\',\'type\':\'Normal\',\'desc\':\'If this attack does not miss, the effects of Reflect, Light Screen, and Aurora Veil end for the target\'s side of the field before damage is calculated. If the user\'s current form is a Paldean Tauros, this move\'s type changes to match. Fighting type for Combat Breed, Fire type for Blaze Breed, and Water type for Aqua Breed.\',\'shortDesc\':\'Destroys screens. Type depends on user\'s form.\'}"),
("ragingfury", "Raging Fury", "Fire", "Physical", 120, "100", 10, 0, "randomNormal", "The user spends two or three turns locked into this move and becomes confused immediately after its move on the last turn of the effect if it is not already. This move targets an opposing Pokemon at random on each turn. If the user is prevented from moving, is asleep at the beginning of a turn, or the attack is not successful against the target on the first turn of the effect or the second turn of a three-turn effect, the effect ends without causing confusion. If this move is called by Sleep Talk and the user is asleep, the move is used for one turn and does not confuse the user.", "Lasts 2-3 turns. Confuses the user afterwards.", "{\'protect\':1,\'mirror\':1}", NULL, NULL, NULL, NULL, "{\'volatileStatus\':\'lockedmove\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':833,\'accuracy\':100,\'basePower\':120,\'category\':\'Physical\',\'name\':\'Raging Fury\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1},\'self\':{\'volatileStatus\':\'lockedmove\'},\'target\':\'randomNormal\',\'type\':\'Fire\',\'desc\':\'The user spends two or three turns locked into this move and becomes confused immediately after its move on the last turn of the effect if it is not already. This move targets an opposing Pokemon at random on each turn. If the user is prevented from moving, is asleep at the beginning of a turn, or the attack is not successful against the target on the first turn of the effect or the second turn of a three-turn effect, the effect ends without causing confusion. If this move is called by Sleep Talk and the user is asleep, the move is used for one turn and does not confuse the user.\',\'shortDesc\':\'Lasts 2-3 turns. Confuses the user afterwards.\'}"),
("raindance", "Rain Dance", "Water", "Status", 0, "1", 5, 0, "all", "For 5 turns, the weather becomes Rain Dance. The damage of Water-type attacks is multiplied by 1.5 and the damage of Fire-type attacks is multiplied by 0.5 during the effect. Lasts for 8 turns if the user is holding Damp Rock. Fails if the current weather is Rain Dance.", "For 5 turns, heavy rain powers Water moves.", "{\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "RainDance", NULL, NULL, NULL, NULL, NULL, "{\'num\':240,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Rain Dance\',\'pp\':5,\'priority\':0,\'flags\':{\'metronome\':1},\'weather\':\'RainDance\',\'target\':\'all\',\'type\':\'Water\',\'zMove\':{\'boost\':{\'spe\':1}},\'contestType\':\'Beautiful\',\'desc\':\'For 5 turns, the weather becomes Rain Dance. The damage of Water-type attacks is multiplied by 1.5 and the damage of Fire-type attacks is multiplied by 0.5 during the effect. Lasts for 8 turns if the user is holding Damp Rock. Fails if the current weather is Rain Dance.\',\'shortDesc\':\'For 5 turns, heavy rain powers Water moves.\'}"),
("rapidspin", "Rapid Spin", "Normal", "Physical", 50, "100", 40, 0, "normal", "If this move is successful and the user has not fainted, the effects of Leech Seed and binding moves end for the user, and all hazards are removed from the user\'s side of the field. Has a 100% chance to raise the user\'s Speed by 1 stage.", "Free user from hazards/bind/Leech Seed; +1 Spe.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':100,\'self\':{\'boosts\':{\'spe\':1}}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':229,\'accuracy\':100,\'basePower\':50,\'category\':\'Physical\',\'name\':\'Rapid Spin\',\'pp\':40,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':100,\'self\':{\'boosts\':{\'spe\':1}}},\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Cool\',\'desc\':\'If this move is successful and the user has not fainted, the effects of Leech Seed and binding moves end for the user, and all hazards are removed from the user\'s side of the field. Has a 100% chance to raise the user\'s Speed by 1 stage.\',\'shortDesc\':\'Free user from hazards\\/bind\\/Leech Seed; +1 Spe.\'}"),
("razorleaf", "Razor Leaf", "Grass", "Physical", 55, "95", 25, 0, "allAdjacentFoes", "Has a higher chance for a critical hit.", "High critical hit ratio. Hits adjacent foes.", "{\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':75,\'accuracy\':95,\'basePower\':55,\'category\':\'Physical\',\'name\':\'Razor Leaf\',\'pp\':25,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1},\'critRatio\':2,\'target\':\'allAdjacentFoes\',\'type\':\'Grass\',\'contestType\':\'Cool\',\'desc\':\'Has a higher chance for a critical hit.\',\'shortDesc\':\'High critical hit ratio. Hits adjacent foes.\'}"),
("razorshell", "Razor Shell", "Water", "Physical", 75, "95", 10, 0, "normal", "Has a 50% chance to lower the target\'s Defense by 1 stage.", "50% chance to lower the target\'s Defense by 1.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1}", "{\'chance\':50,\'boosts\':{\'def\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':534,\'accuracy\':95,\'basePower\':75,\'category\':\'Physical\',\'name\':\'Razor Shell\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'slicing\':1},\'secondary\':{\'chance\':50,\'boosts\':{\'def\':-1}},\'target\':\'normal\',\'type\':\'Water\',\'contestType\':\'Cool\',\'desc\':\'Has a 50% chance to lower the target\'s Defense by 1 stage.\',\'shortDesc\':\'50% chance to lower the target\'s Defense by 1.\'}"),
("razorwind", "Razor Wind", "Normal", "Special", 80, "100", 10, 0, "allAdjacentFoes", "Has a higher chance for a critical hit. This attack charges on the first turn and executes on the second. If the user is holding a Power Herb, the move completes in one turn.", "Charges, then hits foe(s) turn 2. High crit ratio.", "{\'charge\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'nosleeptalk\':1,\'failinstruct\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':13,\'accuracy\':100,\'basePower\':80,\'category\':\'Special\',\'isNonstandard\':\'Past\',\'name\':\'Razor Wind\',\'pp\':10,\'priority\':0,\'flags\':{\'charge\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'nosleeptalk\':1,\'failinstruct\':1},\'critRatio\':2,\'target\':\'allAdjacentFoes\',\'type\':\'Normal\',\'contestType\':\'Cool\',\'desc\':\'Has a higher chance for a critical hit. This attack charges on the first turn and executes on the second. If the user is holding a Power Herb, the move completes in one turn.\',\'shortDesc\':\'Charges, then hits foe(s) turn 2. High crit ratio.\'}"),
("recover", "Recover", "Normal", "Status", 0, "1", 5, 0, "self", "The user restores 1/2 of its maximum HP, rounded half up.", "Heals the user by 50% of its max HP.", "{\'snatch\':1,\'heal\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "[1,2]", NULL, NULL, "{\'num\':105,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Recover\',\'pp\':5,\'priority\':0,\'flags\':{\'snatch\':1,\'heal\':1,\'metronome\':1},\'heal\':[1,2],\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Clever\',\'desc\':\'The user restores 1\\/2 of its maximum HP, rounded half up.\',\'shortDesc\':\'Heals the user by 50% of its max HP.\'}"),
("recycle", "Recycle", "Normal", "Status", 0, "1", 10, 0, "self", "The user regains the item it last used. Fails if the user is holding an item, if the user has not held an item, if the item was a popped Air Balloon, if the item was picked up by a Pokemon with the Pickup Ability, or if the item was lost to Bug Bite, Corrosive Gas, Covet, Incinerate, Knock Off, Pluck, or Thief. Items thrown with Fling can be regained.", "Restores the item the user last used.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':278,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Recycle\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'boost\':{\'spe\':2}},\'contestType\':\'Clever\',\'desc\':\'The user regains the item it last used. Fails if the user is holding an item, if the user has not held an item, if the item was a popped Air Balloon, if the item was picked up by a Pokemon with the Pickup Ability, or if the item was lost to Bug Bite, Corrosive Gas, Covet, Incinerate, Knock Off, Pluck, or Thief. Items thrown with Fling can be regained.\',\'shortDesc\':\'Restores the item the user last used.\'}"),
("reflect", "Reflect", "Psychic", "Status", 0, "1", 20, 0, "allySide", "For 5 turns, the user and its party members take 0.5x damage from physical attacks, or 0.66x damage if in a Double Battle. Damage is not reduced further with Aurora Veil. Critical hits ignore this effect. It is removed from the user\'s side if the user or an ally is successfully hit by Brick Break, Psychic Fangs, or Defog. Lasts for 8 turns if the user is holding Light Clay. Fails if the effect is already active on the user\'s side.", "For 5 turns, physical damage to allies is halved.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':5,\'onSideResidualOrder\':26,\'onSideResidualSubOrder\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':115,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Reflect\',\'pp\':20,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'sideCondition\':\'reflect\',\'condition\':{\'duration\':5,\'onSideResidualOrder\':26,\'onSideResidualSubOrder\':1},\'target\':\'allySide\',\'type\':\'Psychic\',\'zMove\':{\'boost\':{\'def\':1}},\'contestType\':\'Clever\',\'desc\':\'For 5 turns, the user and its party members take 0.5x damage from physical attacks, or 0.66x damage if in a Double Battle. Damage is not reduced further with Aurora Veil. Critical hits ignore this effect. It is removed from the user\'s side if the user or an ally is successfully hit by Brick Break, Psychic Fangs, or Defog. Lasts for 8 turns if the user is holding Light Clay. Fails if the effect is already active on the user\'s side.\',\'shortDesc\':\'For 5 turns, physical damage to allies is halved.\'}"),
("reflecttype", "Reflect Type", "Normal", "Status", 0, "1", 15, 0, "normal", "Causes the user\'s types to become the same as the current types of the target. If the target\'s current types include typeless and a non-added type, typeless is ignored. If the target\'s current types include typeless and an added type from Forest\'s Curse or Trick-or-Treat, typeless is copied as the Normal type instead. Fails if the user is an Arceus or a Silvally, if the user is Terastallized, or if the target\'s current type is typeless alone.", "User becomes the same type as the target.", "{\'protect\':1,\'bypasssub\':1,\'allyanim\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':513,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Reflect Type\',\'pp\':15,\'priority\':0,\'flags\':{\'protect\':1,\'bypasssub\':1,\'allyanim\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'boost\':{\'spa\':1}},\'contestType\':\'Clever\',\'desc\':\'Causes the user\'s types to become the same as the current types of the target. If the target\'s current types include typeless and a non-added type, typeless is ignored. If the target\'s current types include typeless and an added type from Forest\'s Curse or Trick-or-Treat, typeless is copied as the Normal type instead. Fails if the user is an Arceus or a Silvally, if the user is Terastallized, or if the target\'s current type is typeless alone.\',\'shortDesc\':\'User becomes the same type as the target.\'}"),
("refresh", "Refresh", "Normal", "Status", 0, "1", 20, 0, "self", "The user cures its burn, poison, or paralysis. Fails if the user is not burned, poisoned, or paralyzed.", "User cures its burn, poison, or paralysis.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':287,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Refresh\',\'pp\':20,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'heal\'},\'contestType\':\'Cute\',\'desc\':\'The user cures its burn, poison, or paralysis. Fails if the user is not burned, poisoned, or paralyzed.\',\'shortDesc\':\'User cures its burn, poison, or paralysis.\'}"),
("relicsong", "Relic Song", "Normal", "Special", 75, "100", 10, 0, "allAdjacentFoes", "Has a 10% chance to cause the target to fall asleep. If this move is successful on at least one target and the user is a Meloetta, it changes to Pirouette Forme if it is currently in Aria Forme, or changes to Aria Forme if it is currently in Pirouette Forme. This forme change does not happen if the Meloetta has the Sheer Force Ability. The Pirouette Forme reverts to Aria Forme when Meloetta is not active.", "10% chance to sleep foe(s). Meloetta transforms.", "{\'protect\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1}", "{\'chance\':10,\'status\':\'slp\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':547,\'accuracy\':100,\'basePower\':75,\'category\':\'Special\',\'name\':\'Relic Song\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1},\'secondary\':{\'chance\':10,\'status\':\'slp\'},\'target\':\'allAdjacentFoes\',\'type\':\'Normal\',\'contestType\':\'Beautiful\',\'desc\':\'Has a 10% chance to cause the target to fall asleep. If this move is successful on at least one target and the user is a Meloetta, it changes to Pirouette Forme if it is currently in Aria Forme, or changes to Aria Forme if it is currently in Pirouette Forme. This forme change does not happen if the Meloetta has the Sheer Force Ability. The Pirouette Forme reverts to Aria Forme when Meloetta is not active.\',\'shortDesc\':\'10% chance to sleep foe(s). Meloetta transforms.\'}"),
("rest", "Rest", "Psychic", "Status", 0, "1", 5, 0, "self", "The user falls asleep for the next two turns and restores all of its HP, curing itself of any non-volatile status condition in the process. Fails if the user has full HP, is already asleep, or if another effect is preventing sleep.", "User sleeps 2 turns and restores HP and status.", "{\'snatch\':1,\'heal\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':156,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Rest\',\'pp\':5,\'priority\':0,\'flags\':{\'snatch\':1,\'heal\':1,\'metronome\':1},\'target\':\'self\',\'type\':\'Psychic\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Cute\',\'desc\':\'The user falls asleep for the next two turns and restores all of its HP, curing itself of any non-volatile status condition in the process. Fails if the user has full HP, is already asleep, or if another effect is preventing sleep.\',\'shortDesc\':\'User sleeps 2 turns and restores HP and status.\'}"),
("retaliate", "Retaliate", "Normal", "Physical", 70, "100", 5, 0, "normal", "Power doubles if one of the user\'s party members fainted last turn.", "Power doubles if an ally fainted last turn.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':514,\'accuracy\':100,\'basePower\':70,\'category\':\'Physical\',\'name\':\'Retaliate\',\'pp\':5,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Cool\',\'desc\':\'Power doubles if one of the user\'s party members fainted last turn.\',\'shortDesc\':\'Power doubles if an ally fainted last turn.\'}"),
("return", "Return", "Normal", "Physical", 0, "100", 20, 0, "normal", "Power is equal to the greater of (user\'s Happiness * 2/5), rounded down, or 1.", "Max 102 power at maximum Happiness.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':216,\'accuracy\':100,\'basePower\':0,\'basePowerCallback\':true,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Return\',\'pp\':20,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'basePower\':160},\'maxMove\':{\'basePower\':130},\'contestType\':\'Cute\',\'desc\':\'Power is equal to the greater of (user\'s Happiness * 2\\/5), rounded down, or 1.\',\'shortDesc\':\'Max 102 power at maximum Happiness.\'}"),
("revelationdance", "Revelation Dance", "Normal", "Special", 90, "100", 15, 0, "normal", "This move\'s type depends on the user\'s primary type. If the user\'s primary type is typeless, this move\'s type is the user\'s secondary type if it has one, otherwise the added type from Forest\'s Curse or Trick-or-Treat. This move is typeless if the user\'s type is typeless alone.", "Type varies based on the user\'s primary type.", "{\'protect\':1,\'mirror\':1,\'dance\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':686,\'accuracy\':100,\'basePower\':90,\'category\':\'Special\',\'name\':\'Revelation Dance\',\'pp\':15,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'dance\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Beautiful\',\'desc\':\'This move\'s type depends on the user\'s primary type. If the user\'s primary type is typeless, this move\'s type is the user\'s secondary type if it has one, otherwise the added type from Forest\'s Curse or Trick-or-Treat. This move is typeless if the user\'s type is typeless alone.\',\'shortDesc\':\'Type varies based on the user\'s primary type.\'}"),
("revenge", "Revenge", "Fighting", "Physical", 60, "100", 10, -4, "normal", "Power doubles if the user was hit by the target this turn.", "Power doubles if user is damaged by the target.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':279,\'accuracy\':100,\'basePower\':60,\'basePowerCallback\':true,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Revenge\',\'pp\':10,\'priority\':-4,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Fighting\',\'contestType\':\'Tough\',\'desc\':\'Power doubles if the user was hit by the target this turn.\',\'shortDesc\':\'Power doubles if user is damaged by the target.\'}"),
("reversal", "Reversal", "Fighting", "Physical", 0, "100", 15, 0, "normal", "The power of this move is 20 if X is 33 to 48, 40 if X is 17 to 32, 80 if X is 10 to 16, 100 if X is 5 to 9, 150 if X is 2 to 4, and 200 if X is 0 or 1, where X is equal to (user\'s current HP * 48 / user\'s maximum HP), rounded down.", "More power the less HP the user has left.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':179,\'accuracy\':100,\'basePower\':0,\'basePowerCallback\':true,\'category\':\'Physical\',\'name\':\'Reversal\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Fighting\',\'zMove\':{\'basePower\':160},\'contestType\':\'Cool\',\'desc\':\'The power of this move is 20 if X is 33 to 48, 40 if X is 17 to 32, 80 if X is 10 to 16, 100 if X is 5 to 9, 150 if X is 2 to 4, and 200 if X is 0 or 1, where X is equal to (user\'s current HP * 48 \\/ user\'s maximum HP), rounded down.\',\'shortDesc\':\'More power the less HP the user has left.\'}"),
("revivalblessing", "Revival Blessing", "Normal", "Status", 0, "1", 1, 0, "self", "A fainted party member is selected and revived with 1/2 its max HP, rounded down. Fails if there are no fainted party members.", "Revives a fainted Pokemon to 50% HP.", "{\'heal\':1,\'nosketch\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':863,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Revival Blessing\',\'pp\':1,\'noPPBoosts\':true,\'priority\':0,\'flags\':{\'heal\':1,\'nosketch\':1},\'slotCondition\':\'revivalblessing\',\'selfSwitch\':true,\'condition\':{\'duration\':1},\'target\':\'self\',\'type\':\'Normal\',\'desc\':\'A fainted party member is selected and revived with 1\\/2 its max HP, rounded down. Fails if there are no fainted party members.\',\'shortDesc\':\'Revives a fainted Pokemon to 50% HP.\'}"),
("risingvoltage", "Rising Voltage", "Electric", "Special", 70, "100", 20, 0, "normal", "If the current terrain is Electric Terrain and the target is grounded, this move\'s power is doubled.", "2x power if target is grounded in Electric Terrain.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':804,\'accuracy\':100,\'basePower\':70,\'basePowerCallback\':true,\'category\':\'Special\',\'name\':\'Rising Voltage\',\'pp\':20,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Electric\',\'maxMove\':{\'basePower\':140},\'desc\':\'If the current terrain is Electric Terrain and the target is grounded, this move\'s power is doubled.\',\'shortDesc\':\'2x power if target is grounded in Electric Terrain.\'}"),
("roar", "Roar", "Normal", "Status", 0, "1", 20, -6, "normal", "The target is forced to switch out and be replaced with a random unfainted ally. Fails if the target is the last unfainted Pokemon in its party, or if the target used Ingrain previously or has the Suction Cups Ability.", "Forces the target to switch to a random ally.", "{\'reflectable\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1,\'allyanim\':1,\'metronome\':1,\'noassist\':1,\'failcopycat\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':46,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Roar\',\'pp\':20,\'priority\':-6,\'flags\':{\'reflectable\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1,\'allyanim\':1,\'metronome\':1,\'noassist\':1,\'failcopycat\':1},\'forceSwitch\':true,\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'boost\':{\'def\':1}},\'contestType\':\'Cool\',\'desc\':\'The target is forced to switch out and be replaced with a random unfainted ally. Fails if the target is the last unfainted Pokemon in its party, or if the target used Ingrain previously or has the Suction Cups Ability.\',\'shortDesc\':\'Forces the target to switch to a random ally.\'}");
INSERT INTO `api_moves` (`id`, `name`, `type`, `category`, `basePower`, `accuracy`, `pp`, `priority`, `target`, `desc`, `shortDesc`, `flags`, `secondary`, `secondaries`, `drain`, `boosts`, `self`, `selfBoost`, `condition`, `volatileStatus`, `status`, `weather`, `terrain`, `pseudoWeather`, `heal`, `recoil`, `multihit`, `raw_json`) VALUES
("roaroftime", "Roar of Time", "Dragon", "Special", 150, "90", 5, 0, "normal", "If this move is successful, the user must recharge on the following turn and cannot select a move.", "User cannot move next turn.", "{\'recharge\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, "{\'volatileStatus\':\'mustrecharge\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':459,\'accuracy\':90,\'basePower\':150,\'category\':\'Special\',\'name\':\'Roar of Time\',\'pp\':5,\'priority\':0,\'flags\':{\'recharge\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'self\':{\'volatileStatus\':\'mustrecharge\'},\'target\':\'normal\',\'type\':\'Dragon\',\'contestType\':\'Beautiful\',\'desc\':\'If this move is successful, the user must recharge on the following turn and cannot select a move.\',\'shortDesc\':\'User cannot move next turn.\'}"),
("rockblast", "Rock Blast", "Rock", "Physical", 25, "90", 10, 0, "normal", "Hits two to five times. Has a 35% chance to hit two or three times and a 15% chance to hit four or five times. If one of the hits breaks the target\'s substitute, it will take damage for the remaining hits. If the user has the Skill Link Ability, this move will always hit five times. If the user is holding Loaded Dice, this move will hit 4-5 times.", "Hits 2-5 times in one turn.", "{\'protect\':1,\'mirror\':1,\'metronome\':1,\'bullet\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "[2,5]", "{\'num\':350,\'accuracy\':90,\'basePower\':25,\'category\':\'Physical\',\'name\':\'Rock Blast\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1,\'bullet\':1},\'multihit\':[2,5],\'target\':\'normal\',\'type\':\'Rock\',\'zMove\':{\'basePower\':140},\'maxMove\':{\'basePower\':130},\'contestType\':\'Tough\',\'desc\':\'Hits two to five times. Has a 35% chance to hit two or three times and a 15% chance to hit four or five times. If one of the hits breaks the target\'s substitute, it will take damage for the remaining hits. If the user has the Skill Link Ability, this move will always hit five times. If the user is holding Loaded Dice, this move will hit 4-5 times.\',\'shortDesc\':\'Hits 2-5 times in one turn.\'}"),
("rockclimb", "Rock Climb", "Normal", "Physical", 90, "85", 20, 0, "normal", "Has a 20% chance to confuse the target.", "20% chance to confuse the target.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':20,\'volatileStatus\':\'confusion\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':431,\'accuracy\':85,\'basePower\':90,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Rock Climb\',\'pp\':20,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':20,\'volatileStatus\':\'confusion\'},\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Tough\',\'desc\':\'Has a 20% chance to confuse the target.\',\'shortDesc\':\'20% chance to confuse the target.\'}"),
("rockpolish", "Rock Polish", "Rock", "Status", 0, "1", 20, 0, "self", "Raises the user\'s Speed by 2 stages.", "Raises the user\'s Speed by 2.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, "{\'spe\':2}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':397,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Rock Polish\',\'pp\':20,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'boosts\':{\'spe\':2},\'target\':\'self\',\'type\':\'Rock\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Tough\',\'desc\':\'Raises the user\'s Speed by 2 stages.\',\'shortDesc\':\'Raises the user\'s Speed by 2.\'}"),
("rockslide", "Rock Slide", "Rock", "Physical", 75, "90", 10, 0, "allAdjacentFoes", "Has a 30% chance to make the target flinch.", "30% chance to make the foe(s) flinch.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':30,\'volatileStatus\':\'flinch\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':157,\'accuracy\':90,\'basePower\':75,\'category\':\'Physical\',\'name\':\'Rock Slide\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':30,\'volatileStatus\':\'flinch\'},\'target\':\'allAdjacentFoes\',\'type\':\'Rock\',\'contestType\':\'Tough\',\'desc\':\'Has a 30% chance to make the target flinch.\',\'shortDesc\':\'30% chance to make the foe(s) flinch.\'}"),
("rocksmash", "Rock Smash", "Fighting", "Physical", 40, "100", 15, 0, "normal", "Has a 50% chance to lower the target\'s Defense by 1 stage.", "50% chance to lower the target\'s Defense by 1.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':50,\'boosts\':{\'def\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':249,\'accuracy\':100,\'basePower\':40,\'category\':\'Physical\',\'name\':\'Rock Smash\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':50,\'boosts\':{\'def\':-1}},\'target\':\'normal\',\'type\':\'Fighting\',\'contestType\':\'Tough\',\'desc\':\'Has a 50% chance to lower the target\'s Defense by 1 stage.\',\'shortDesc\':\'50% chance to lower the target\'s Defense by 1.\'}"),
