("shadowclaw", "Shadow Claw", "Ghost", "Physical", 70, "100", 15, 0, "normal", "Has a higher chance for a critical hit.", "High critical hit ratio.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':421,\'accuracy\':100,\'basePower\':70,\'category\':\'Physical\',\'name\':\'Shadow Claw\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'critRatio\':2,\'target\':\'normal\',\'type\':\'Ghost\',\'contestType\':\'Cool\',\'desc\':\'Has a higher chance for a critical hit.\',\'shortDesc\':\'High critical hit ratio.\'}"),
("shadowforce", "Shadow Force", "Ghost", "Physical", 120, "100", 5, 0, "normal", "If this move is successful, it breaks through the target\'s Baneful Bunker, Detect, King\'s Shield, Protect, or Spiky Shield for this turn, allowing other Pokemon to attack the target normally. If the target\'s side is protected by Crafty Shield, Mat Block, Quick Guard, or Wide Guard, that protection is also broken for this turn and other Pokemon may attack the target\'s side normally. This attack charges on the first turn and executes on the second. On the first turn, the user avoids all attacks. If the user is holding a Power Herb, the move completes in one turn.", "Disappears turn 1. Hits turn 2. Breaks protection.", "{\'contact\':1,\'charge\':1,\'mirror\':1,\'metronome\':1,\'nosleeptalk\':1,\'noassist\':1,\'failinstruct\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':2,\'onInvulnerability\':false}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':467,\'accuracy\':100,\'basePower\':120,\'category\':\'Physical\',\'name\':\'Shadow Force\',\'pp\':5,\'priority\':0,\'flags\':{\'contact\':1,\'charge\':1,\'mirror\':1,\'metronome\':1,\'nosleeptalk\':1,\'noassist\':1,\'failinstruct\':1},\'breaksProtect\':true,\'condition\':{\'duration\':2,\'onInvulnerability\':false},\'target\':\'normal\',\'type\':\'Ghost\',\'contestType\':\'Cool\',\'desc\':\'If this move is successful, it breaks through the target\'s Baneful Bunker, Detect, King\'s Shield, Protect, or Spiky Shield for this turn, allowing other Pokemon to attack the target normally. If the target\'s side is protected by Crafty Shield, Mat Block, Quick Guard, or Wide Guard, that protection is also broken for this turn and other Pokemon may attack the target\'s side normally. This attack charges on the first turn and executes on the second. On the first turn, the user avoids all attacks. If the user is holding a Power Herb, the move completes in one turn.\',\'shortDesc\':\'Disappears turn 1. Hits turn 2. Breaks protection.\'}"),
("shadowpunch", "Shadow Punch", "Ghost", "Physical", 60, "1", 20, 0, "normal", "This move does not check accuracy.", "This move does not check accuracy.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'punch\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':325,\'accuracy\':true,\'basePower\':60,\'category\':\'Physical\',\'name\':\'Shadow Punch\',\'pp\':20,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'punch\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Ghost\',\'contestType\':\'Clever\',\'desc\':\'This move does not check accuracy.\',\'shortDesc\':\'This move does not check accuracy.\'}"),
("shadowsneak", "Shadow Sneak", "Ghost", "Physical", 40, "100", 30, 1, "normal", "No additional effect.", "Usually goes first.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':425,\'accuracy\':100,\'basePower\':40,\'category\':\'Physical\',\'name\':\'Shadow Sneak\',\'pp\':30,\'priority\':1,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Ghost\',\'contestType\':\'Clever\',\'desc\':\'No additional effect.\',\'shortDesc\':\'Usually goes first.\'}"),
("shadowstrike", "Shadow Strike", "Ghost", "Physical", 80, "95", 10, 0, "normal", "Has a 50% chance to lower the target\'s Defense by 1 stage.", "50% chance to lower the target\'s Defense by 1.", "{\'contact\':1,\'protect\':1,\'mirror\':1}", "{\'chance\':50,\'boosts\':{\'def\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':-2,\'accuracy\':95,\'basePower\':80,\'category\':\'Physical\',\'isNonstandard\':\'CAP\',\'name\':\'Shadow Strike\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1},\'secondary\':{\'chance\':50,\'boosts\':{\'def\':-1}},\'target\':\'normal\',\'type\':\'Ghost\',\'contestType\':\'Clever\',\'desc\':\'Has a 50% chance to lower the target\'s Defense by 1 stage.\',\'shortDesc\':\'50% chance to lower the target\'s Defense by 1.\'}"),
("sharpen", "Sharpen", "Normal", "Status", 0, "1", 30, 0, "self", "Raises the user\'s Attack by 1 stage.", "Raises the user\'s Attack by 1.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, "{\'atk\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':159,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'isNonstandard\':\'Past\',\'name\':\'Sharpen\',\'pp\':30,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'boosts\':{\'atk\':1},\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'boost\':{\'atk\':1}},\'contestType\':\'Cute\',\'desc\':\'Raises the user\'s Attack by 1 stage.\',\'shortDesc\':\'Raises the user\'s Attack by 1.\'}"),
("shatteredpsyche", "Shattered Psyche", "Psychic", "Physical", 1, "1", 1, 0, "normal", "Power is equal to the base move\'s Z-Power.", "Power is equal to the base move\'s Z-Power.", "[]", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':648,\'accuracy\':true,\'basePower\':1,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Shattered Psyche\',\'pp\':1,\'priority\':0,\'flags\':[],\'isZ\':\'psychiumz\',\'target\':\'normal\',\'type\':\'Psychic\',\'contestType\':\'Cool\',\'desc\':\'Power is equal to the base move\'s Z-Power.\',\'shortDesc\':\'Power is equal to the base move\'s Z-Power.\'}"),
("shedtail", "Shed Tail", "Normal", "Status", 0, "1", 10, 0, "self", "The user takes 1/2 of its maximum HP, rounded up, and creates a substitute that has 1/4 of the user\'s maximum HP, rounded down. The user is replaced with another Pokemon in its party and the selected Pokemon has the substitute transferred to it. Fails if the user would faint, or if there are no unfainted party members.", "User takes 1/2 its max HP to pass a substitute.", "[]", NULL, NULL, NULL, NULL, "[]", NULL, NULL, "substitute", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':880,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Shed Tail\',\'pp\':10,\'priority\':0,\'flags\':[],\'volatileStatus\':\'substitute\',\'self\':[],\'selfSwitch\':\'shedtail\',\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'desc\':\'The user takes 1\\/2 of its maximum HP, rounded up, and creates a substitute that has 1\\/4 of the user\'s maximum HP, rounded down. The user is replaced with another Pokemon in its party and the selected Pokemon has the substitute transferred to it. Fails if the user would faint, or if there are no unfainted party members.\',\'shortDesc\':\'User takes 1\\/2 its max HP to pass a substitute.\'}");
INSERT INTO `api_moves` (`id`, `name`, `type`, `category`, `basePower`, `accuracy`, `pp`, `priority`, `target`, `desc`, `shortDesc`, `flags`, `secondary`, `secondaries`, `drain`, `boosts`, `self`, `selfBoost`, `condition`, `volatileStatus`, `status`, `weather`, `terrain`, `pseudoWeather`, `heal`, `recoil`, `multihit`, `raw_json`) VALUES
("sheercold", "Sheer Cold", "Ice", "Special", 0, "30", 5, 0, "normal", "Deals damage to the target equal to the target\'s maximum HP. Ignores accuracy and evasiveness modifiers. This attack\'s accuracy is equal to (user\'s level - target\'s level + X)%, where X is 30 if the user is an Ice type and 20 otherwise, and fails if the target is at a higher level. Ice-type Pokemon and Pokemon with the Sturdy Ability are immune.", "OHKOs non-Ice targets. Fails if user\'s lower level.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':329,\'accuracy\':30,\'basePower\':0,\'category\':\'Special\',\'name\':\'Sheer Cold\',\'pp\':5,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'ohko\':\'Ice\',\'target\':\'normal\',\'type\':\'Ice\',\'zMove\':{\'basePower\':180},\'maxMove\':{\'basePower\':130},\'contestType\':\'Beautiful\',\'desc\':\'Deals damage to the target equal to the target\'s maximum HP. Ignores accuracy and evasiveness modifiers. This attack\'s accuracy is equal to (user\'s level - target\'s level + X)%, where X is 30 if the user is an Ice type and 20 otherwise, and fails if the target is at a higher level. Ice-type Pokemon and Pokemon with the Sturdy Ability are immune.\',\'shortDesc\':\'OHKOs non-Ice targets. Fails if user\'s lower level.\'}"),
("shellsidearm", "Shell Side Arm", "Poison", "Special", 90, "100", 10, 0, "normal", "Has a 20% chance to poison the target. This move becomes a physical attack that makes contact if the value of ((((2 * the user\'s level / 5 + 2) * 90 * X) / Y) / 50), where X is the user\'s Attack stat and Y is the target\'s Defense stat, is greater than the same value where X is the user\'s Special Attack stat and Y is the target\'s Special Defense stat. No stat modifiers other than stat stage changes are considered for this purpose. If the two values are equal, this move chooses a damage category at random.", "20% psn. Physical+contact if it would be stronger.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':20,\'status\':\'psn\'}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':801,\'accuracy\':100,\'basePower\':90,\'category\':\'Special\',\'name\':\'Shell Side Arm\',\'pp\':10,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':20,\'status\':\'psn\'},\'target\':\'normal\',\'type\':\'Poison\',\'desc\':\'Has a 20% chance to poison the target. This move becomes a physical attack that makes contact if the value of ((((2 * the user\'s level \\/ 5 + 2) * 90 * X) \\/ Y) \\/ 50), where X is the user\'s Attack stat and Y is the target\'s Defense stat, is greater than the same value where X is the user\'s Special Attack stat and Y is the target\'s Special Defense stat. No stat modifiers other than stat stage changes are considered for this purpose. If the two values are equal, this move chooses a damage category at random.\',\'shortDesc\':\'20% psn. Physical+contact if it would be stronger.\'}"),
("shellsmash", "Shell Smash", "Normal", "Status", 0, "1", 15, 0, "self", "Lowers the user\'s Defense and Special Defense by 1 stage. Raises the user\'s Attack, Special Attack, and Speed by 2 stages.", "Lowers Def, SpD by 1; raises Atk, SpA, Spe by 2.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, "{\'def\':-1,\'spd\':-1,\'atk\':2,\'spa\':2,\'spe\':2}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':504,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Shell Smash\',\'pp\':15,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'boosts\':{\'def\':-1,\'spd\':-1,\'atk\':2,\'spa\':2,\'spe\':2},\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Tough\',\'desc\':\'Lowers the user\'s Defense and Special Defense by 1 stage. Raises the user\'s Attack, Special Attack, and Speed by 2 stages.\',\'shortDesc\':\'Lowers Def, SpD by 1; raises Atk, SpA, Spe by 2.\'}"),
("shelltrap", "Shell Trap", "Fire", "Special", 150, "100", 5, -3, "allAdjacentFoes", "Fails unless the user is hit by a physical attack from an opponent this turn before it can execute the move. If the user was hit and has not fainted, it attacks immediately after being hit, and the effect ends. If the opponent\'s physical attack had a secondary effect removed by the Sheer Force Ability, it does not count for the purposes of this effect.", "User must take physical damage before moving.", "{\'protect\':1,\'failmefirst\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failinstruct\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'duration\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':704,\'accuracy\':100,\'basePower\':150,\'category\':\'Special\',\'isNonstandard\':\'Past\',\'name\':\'Shell Trap\',\'pp\':5,\'priority\':-3,\'flags\':{\'protect\':1,\'failmefirst\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failinstruct\':1},\'condition\':{\'duration\':1},\'target\':\'allAdjacentFoes\',\'type\':\'Fire\',\'contestType\':\'Tough\',\'desc\':\'Fails unless the user is hit by a physical attack from an opponent this turn before it can execute the move. If the user was hit and has not fainted, it attacks immediately after being hit, and the effect ends. If the opponent\'s physical attack had a secondary effect removed by the Sheer Force Ability, it does not count for the purposes of this effect.\',\'shortDesc\':\'User must take physical damage before moving.\'}"),
("shelter", "Shelter", "Steel", "Status", 0, "1", 10, 0, "self", "Raises the user\'s Defense by 2 stages.", "Raises the user\'s Defense by 2.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, "{\'def\':2}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':842,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Shelter\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'boosts\':{\'def\':2},\'target\':\'self\',\'type\':\'Steel\',\'desc\':\'Raises the user\'s Defense by 2 stages.\',\'shortDesc\':\'Raises the user\'s Defense by 2.\'}"),
("shiftgear", "Shift Gear", "Steel", "Status", 0, "1", 10, 0, "self", "Raises the user\'s Speed by 2 stages and its Attack by 1 stage.", "Raises the user\'s Speed by 2 and Attack by 1.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, "{\'spe\':2,\'atk\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':508,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Shift Gear\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'boosts\':{\'spe\':2,\'atk\':1},\'target\':\'self\',\'type\':\'Steel\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Clever\',\'desc\':\'Raises the user\'s Speed by 2 stages and its Attack by 1 stage.\',\'shortDesc\':\'Raises the user\'s Speed by 2 and Attack by 1.\'}"),
("shockwave", "Shock Wave", "Electric", "Special", 60, "1", 20, 0, "normal", "This move does not check accuracy.", "This move does not check accuracy.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':351,\'accuracy\':true,\'basePower\':60,\'category\':\'Special\',\'name\':\'Shock Wave\',\'pp\':20,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Electric\',\'contestType\':\'Cool\',\'desc\':\'This move does not check accuracy.\',\'shortDesc\':\'This move does not check accuracy.\'}"),
