("struggle", "Struggle", "Normal", "Physical", 50, "1", 1, 0, "randomNormal", "Deals typeless damage to a random opposing Pokemon. If this move was successful, the user loses 1/4 of its maximum HP, rounded half up, and the Rock Head Ability does not prevent this. This move is automatically used if none of the user\'s known moves can be selected.", "User loses 1/4 of its max HP.", "{\'contact\':1,\'protect\':1,\'failencore\':1,\'failmefirst\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failmimic\':1,\'failinstruct\':1,\'nosketch\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':165,\'accuracy\':true,\'basePower\':50,\'category\':\'Physical\',\'name\':\'Struggle\',\'pp\':1,\'noPPBoosts\':true,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'failencore\':1,\'failmefirst\':1,\'nosleeptalk\':1,\'noassist\':1,\'failcopycat\':1,\'failmimic\':1,\'failinstruct\':1,\'nosketch\':1},\'struggleRecoil\':true,\'target\':\'randomNormal\',\'type\':\'Normal\',\'contestType\':\'Tough\',\'desc\':\'Deals typeless damage to a random opposing Pokemon. If this move was successful, the user loses 1\\/4 of its maximum HP, rounded half up, and the Rock Head Ability does not prevent this. This move is automatically used if none of the user\'s known moves can be selected.\',\'shortDesc\':\'User loses 1\\/4 of its max HP.\'}"),
("strugglebug", "Struggle Bug", "Bug", "Special", 50, "100", 20, 0, "allAdjacentFoes", "Has a 100% chance to lower the target\'s Special Attack by 1 stage.", "100% chance to lower the foe(s) Sp. Atk by 1.", "{\'protect\':1,\'mirror\':1,\'metronome\':1}", "{\'chance\':100,\'boosts\':{\'spa\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':522,\'accuracy\':100,\'basePower\':50,\'category\':\'Special\',\'name\':\'Struggle Bug\',\'pp\':20,\'priority\':0,\'flags\':{\'protect\':1,\'mirror\':1,\'metronome\':1},\'secondary\':{\'chance\':100,\'boosts\':{\'spa\':-1}},\'target\':\'allAdjacentFoes\',\'type\':\'Bug\',\'contestType\':\'Cute\',\'desc\':\'Has a 100% chance to lower the target\'s Special Attack by 1 stage.\',\'shortDesc\':\'100% chance to lower the foe(s) Sp. Atk by 1.\'}"),
("stuffcheeks", "Stuff Cheeks", "Normal", "Status", 0, "1", 10, 0, "self", "This move cannot be selected unless the user is holding a Berry. The user eats its Berry and raises its Defense by 2 stages. This effect is not prevented by the Klutz or Unnerve Abilities, or the effects of Embargo or Magic Room. Fails if the user is not holding a Berry.", "Must hold Berry to use. User eats Berry, Def +2.", "{\'snatch\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':747,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Stuff Cheeks\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1,\'metronome\':1},\'target\':\'self\',\'type\':\'Normal\',\'desc\':\'This move cannot be selected unless the user is holding a Berry. The user eats its Berry and raises its Defense by 2 stages. This effect is not prevented by the Klutz or Unnerve Abilities, or the effects of Embargo or Magic Room. Fails if the user is not holding a Berry.\',\'shortDesc\':\'Must hold Berry to use. User eats Berry, Def +2.\'}"),
("stunspore", "Stun Spore", "Grass", "Status", 0, "75", 30, 0, "normal", "Paralyzes the target.", "Paralyzes the target.", "{\'protect\':1,\'reflectable\':1,\'mirror\':1,\'metronome\':1,\'powder\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "par", NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':78,\'accuracy\':75,\'basePower\':0,\'category\':\'Status\',\'name\':\'Stun Spore\',\'pp\':30,\'priority\':0,\'flags\':{\'protect\':1,\'reflectable\':1,\'mirror\':1,\'metronome\':1,\'powder\':1},\'status\':\'par\',\'target\':\'normal\',\'type\':\'Grass\',\'zMove\':{\'boost\':{\'spd\':1}},\'contestType\':\'Clever\',\'desc\':\'Paralyzes the target.\',\'shortDesc\':\'Paralyzes the target.\'}"),
("submission", "Submission", "Fighting", "Physical", 80, "80", 20, 0, "normal", "If the target lost HP, the user takes recoil damage equal to 1/4 the HP lost by the target, rounded half up, but not less than 1 HP.", "Has 1/4 recoil.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "[1,4]", NULL, "{\'num\':66,\'accuracy\':80,\'basePower\':80,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Submission\',\'pp\':20,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'recoil\':[1,4],\'target\':\'normal\',\'type\':\'Fighting\',\'contestType\':\'Cool\',\'desc\':\'If the target lost HP, the user takes recoil damage equal to 1\\/4 the HP lost by the target, rounded half up, but not less than 1 HP.\',\'shortDesc\':\'Has 1\\/4 recoil.\'}");
INSERT INTO `api_moves` (`id`, `name`, `type`, `category`, `basePower`, `accuracy`, `pp`, `priority`, `target`, `desc`, `shortDesc`, `flags`, `secondary`, `secondaries`, `drain`, `boosts`, `self`, `selfBoost`, `condition`, `volatileStatus`, `status`, `weather`, `terrain`, `pseudoWeather`, `heal`, `recoil`, `multihit`, `raw_json`) VALUES
("substitute", "Substitute", "Normal", "Status", 0, "1", 10, 0, "self", "The user takes 1/4 of its maximum HP, rounded down, and puts it into a substitute to take its place in battle. The substitute is removed once enough damage is inflicted on it, if the user switches out or faints, or if any Pokemon uses Tidy Up. Baton Pass can be used to transfer the substitute to an ally, and the substitute will keep its remaining HP. Until the substitute is broken, it receives damage from all attacks made by other Pokemon and shields the user from status effects and stat stage changes caused by other Pokemon. Sound-based moves and Pokemon with the Infiltrator Ability ignore substitutes. The user still takes normal damage from weather and status effects while behind its substitute. If the substitute breaks during a multi-hit attack, the user will take damage from any remaining hits. If a substitute is created while the user is trapped by a binding move, the binding effect ends immediately. Fails if the user does not have enough HP remaining to create a substitute without fainting, or if it already has a substitute.", "User takes 1/4 its max HP to put in a substitute.", "{\'snatch\':1,\'nonsky\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, "{\'onTryPrimaryHitPriority\':-1}", "substitute", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':164,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Substitute\',\'pp\':10,\'priority\':0,\'flags\':{\'snatch\':1,\'nonsky\':1,\'metronome\':1},\'volatileStatus\':\'substitute\',\'condition\':{\'onTryPrimaryHitPriority\':-1},\'target\':\'self\',\'type\':\'Normal\',\'zMove\':{\'effect\':\'clearnegativeboost\'},\'contestType\':\'Cute\',\'desc\':\'The user takes 1\\/4 of its maximum HP, rounded down, and puts it into a substitute to take its place in battle. The substitute is removed once enough damage is inflicted on it, if the user switches out or faints, or if any Pokemon uses Tidy Up. Baton Pass can be used to transfer the substitute to an ally, and the substitute will keep its remaining HP. Until the substitute is broken, it receives damage from all attacks made by other Pokemon and shields the user from status effects and stat stage changes caused by other Pokemon. Sound-based moves and Pokemon with the Infiltrator Ability ignore substitutes. The user still takes normal damage from weather and status effects while behind its substitute. If the substitute breaks during a multi-hit attack, the user will take damage from any remaining hits. If a substitute is created while the user is trapped by a binding move, the binding effect ends immediately. Fails if the user does not have enough HP remaining to create a substitute without fainting, or if it already has a substitute.\',\'shortDesc\':\'User takes 1\\/4 its max HP to put in a substitute.\'}"),
("subzeroslammer", "Subzero Slammer", "Ice", "Physical", 1, "1", 1, 0, "normal", "Power is equal to the base move\'s Z-Power.", "Power is equal to the base move\'s Z-Power.", "[]", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':650,\'accuracy\':true,\'basePower\':1,\'category\':\'Physical\',\'isNonstandard\':\'Past\',\'name\':\'Subzero Slammer\',\'pp\':1,\'priority\':0,\'flags\':[],\'isZ\':\'iciumz\',\'target\':\'normal\',\'type\':\'Ice\',\'contestType\':\'Cool\',\'desc\':\'Power is equal to the base move\'s Z-Power.\',\'shortDesc\':\'Power is equal to the base move\'s Z-Power.\'}"),
("suckerpunch", "Sucker Punch", "Dark", "Physical", 70, "100", 5, 1, "normal", "Fails if the target did not select a physical attack, special attack, or Me First for use this turn, or if the target moves before the user.", "Usually goes first. Fails if target is not attacking.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':389,\'accuracy\':100,\'basePower\':70,\'category\':\'Physical\',\'name\':\'Sucker Punch\',\'pp\':5,\'priority\':1,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Dark\',\'contestType\':\'Clever\',\'desc\':\'Fails if the target did not select a physical attack, special attack, or Me First for use this turn, or if the target moves before the user.\',\'shortDesc\':\'Usually goes first. Fails if target is not attacking.\'}"),
("sunnyday", "Sunny Day", "Fire", "Status", 0, "1", 5, 0, "all", "For 5 turns, the weather becomes Sunny Day. The damage of Fire-type attacks is multiplied by 1.5 and the damage of Water-type attacks is multiplied by 0.5 during the effect. Lasts for 8 turns if the user is holding Heat Rock. Fails if the current weather is Sunny Day.", "For 5 turns, intense sunlight powers Fire moves.", "{\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "sunnyday", NULL, NULL, NULL, NULL, NULL, "{\'num\':241,\'accuracy\':true,\'basePower\':0,\'category\':\'Status\',\'name\':\'Sunny Day\',\'pp\':5,\'priority\':0,\'flags\':{\'metronome\':1},\'weather\':\'sunnyday\',\'target\':\'all\',\'type\':\'Fire\',\'zMove\':{\'boost\':{\'spe\':1}},\'contestType\':\'Beautiful\',\'desc\':\'For 5 turns, the weather becomes Sunny Day. The damage of Fire-type attacks is multiplied by 1.5 and the damage of Water-type attacks is multiplied by 0.5 during the effect. Lasts for 8 turns if the user is holding Heat Rock. Fails if the current weather is Sunny Day.\',\'shortDesc\':\'For 5 turns, intense sunlight powers Fire moves.\'}"),
("sunsteelstrike", "Sunsteel Strike", "Steel", "Physical", 100, "100", 5, 0, "normal", "This move and its effects ignore the Abilities of other Pokemon.", "Ignores the Abilities of other Pokemon.", "{\'contact\':1,\'protect\':1,\'mirror\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':713,\'accuracy\':100,\'basePower\':100,\'category\':\'Physical\',\'name\':\'Sunsteel Strike\',\'pp\':5,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1},\'ignoreAbility\':true,\'target\':\'normal\',\'type\':\'Steel\',\'contestType\':\'Cool\',\'desc\':\'This move and its effects ignore the Abilities of other Pokemon.\',\'shortDesc\':\'Ignores the Abilities of other Pokemon.\'}"),
("supercellslam", "Supercell Slam", "Electric", "Physical", 100, "95", 15, 0, "normal", "If this attack is not successful, the user loses half of its maximum HP, rounded down, as crash damage. Pokemon with the Magic Guard Ability are unaffected by crash damage. Damage doubles and no accuracy check is done if the target has used Minimize while active.", "User is hurt by 50% of its max HP if it misses.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'minimize\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':916,\'accuracy\':95,\'basePower\':100,\'category\':\'Physical\',\'name\':\'Supercell Slam\',\'pp\':15,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1,\'minimize\':1},\'hasCrashDamage\':true,\'target\':\'normal\',\'type\':\'Electric\',\'desc\':\'If this attack is not successful, the user loses half of its maximum HP, rounded down, as crash damage. Pokemon with the Magic Guard Ability are unaffected by crash damage. Damage doubles and no accuracy check is done if the target has used Minimize while active.\',\'shortDesc\':\'User is hurt by 50% of its max HP if it misses.\'}"),
("superfang", "Super Fang", "Normal", "Physical", 0, "90", 10, 0, "normal", "Deals damage to the target equal to half of its current HP, rounded down, but not less than 1 HP.", "Does damage equal to 1/2 target\'s current HP.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':162,\'accuracy\':90,\'basePower\':0,\'category\':\'Physical\',\'name\':\'Super Fang\',\'pp\':10,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'target\':\'normal\',\'type\':\'Normal\',\'contestType\':\'Tough\',\'desc\':\'Deals damage to the target equal to half of its current HP, rounded down, but not less than 1 HP.\',\'shortDesc\':\'Does damage equal to 1\\/2 target\'s current HP.\'}"),
("superpower", "Superpower", "Fighting", "Physical", 120, "100", 5, 0, "normal", "Lowers the user\'s Attack and Defense by 1 stage.", "Lowers the user\'s Attack and Defense by 1.", "{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, "{\'boosts\':{\'atk\':-1,\'def\':-1}}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':276,\'accuracy\':100,\'basePower\':120,\'category\':\'Physical\',\'name\':\'Superpower\',\'pp\':5,\'priority\':0,\'flags\':{\'contact\':1,\'protect\':1,\'mirror\':1,\'metronome\':1},\'self\':{\'boosts\':{\'atk\':-1,\'def\':-1}},\'target\':\'normal\',\'type\':\'Fighting\',\'contestType\':\'Tough\',\'desc\':\'Lowers the user\'s Attack and Defense by 1 stage.\',\'shortDesc\':\'Lowers the user\'s Attack and Defense by 1.\'}"),
("supersonic", "Supersonic", "Normal", "Status", 0, "55", 20, 0, "normal", "Causes the target to become confused.", "Causes the target to become confused.", "{\'protect\':1,\'reflectable\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1,\'metronome\':1}", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "confusion", NULL, NULL, NULL, NULL, NULL, NULL, NULL, "{\'num\':48,\'accuracy\':55,\'basePower\':0,\'category\':\'Status\',\'name\':\'Supersonic\',\'pp\':20,\'priority\':0,\'flags\':{\'protect\':1,\'reflectable\':1,\'mirror\':1,\'sound\':1,\'bypasssub\':1,\'metronome\':1},\'volatileStatus\':\'confusion\',\'target\':\'normal\',\'type\':\'Normal\',\'zMove\':{\'boost\':{\'spe\':1}},\'contestType\':\'Clever\',\'desc\':\'Causes the target to become confused.\',\'shortDesc\':\'Causes the target to become confused.\'}"),
