-- =========================================================
-- BETA RPG DATABASE
-- PHP 8.x + MariaDB 10.7+
-- =========================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

-- Create absolute_beta migrations table

CREATE DATABASE IF NOT EXISTS `migrations`;

USE `migrations`;

CREATE TABLE IF NOT EXISTS `absolute_beta` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `executed_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- absolute_beta tables

use `absolute_beta`;

-- =========================================================
-- DROP TABLES (SAFE RE-IMPORT)
-- =========================================================

DROP TABLE IF EXISTS user_reports;
DROP TABLE IF EXISTS user_bans;
DROP TABLE IF EXISTS user_passwords;
DROP TABLE IF EXISTS user_rpg_state;
DROP TABLE IF EXISTS user_pokemon;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS clans;
DROP TABLE IF EXISTS api_pokedex;

-- =========================================================
-- CLANS
-- =========================================================

CREATE TABLE clans (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name VARCHAR(25) NOT NULL,

  experience INT UNSIGNED NOT NULL DEFAULT 0,
  clan_points INT UNSIGNED NOT NULL DEFAULT 0,

  money BIGINT UNSIGNED NOT NULL DEFAULT 0,
  abso_coins BIGINT UNSIGNED NOT NULL DEFAULT 0,

  avatar VARCHAR(255) DEFAULT '/Pokemon/Sprites/0.png',
  signature TEXT DEFAULT NULL,

  PRIMARY KEY (id),
  UNIQUE KEY uq_clans_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- USERS (CORE IDENTITY)
-- =========================================================

CREATE TABLE users (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  username VARCHAR(32) NOT NULL,


  gender ENUM('Male','Female','Genderless') NOT NULL DEFAULT 'Genderless',

  clan_id INT UNSIGNED DEFAULT NULL,

  avatar VARCHAR(255) DEFAULT 'images/Avatars/1.png',

  playtime INT(12) NOT NULL DEFAULT '0',

  roster_hash VARCHAR(32) DEFAULT NULL,
  auth_code VARCHAR(64) DEFAULT NULL,

  discord_id BIGINT UNSIGNED DEFAULT NULL,

  date_registered INT UNSIGNED NOT NULL,
  last_active INT UNSIGNED DEFAULT NULL,

  last_page VARCHAR(100) DEFAULT NULL,
  status VARCHAR(150) DEFAULT NULL,

  PRIMARY KEY (id),

  UNIQUE KEY uq_users_username (username),
  UNIQUE KEY uq_users_discord (discord_id),

  KEY idx_users_last_active (last_active),
  KEY idx_users_clan_id (clan_id),

  CONSTRAINT fk_users_clan
    FOREIGN KEY (clan_id) REFERENCES clans(id)
    ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- USER RPG STATE (GAME STATE)
-- =========================================================

DROP TABLE IF EXISTS user_rpg_state;
CREATE TABLE user_rpg_state (
  user_id INT UNSIGNED NOT NULL,

  playtime INT UNSIGNED DEFAULT 0,

  money BIGINT UNSIGNED NOT NULL DEFAULT 0,
  abso_coins BIGINT UNSIGNED NOT NULL DEFAULT 0,

  trainer_level INT UNSIGNED NOT NULL DEFAULT 1,
  trainer_exp BIGINT UNSIGNED NOT NULL DEFAULT 0,

  mining_level INT UNSIGNED NOT NULL DEFAULT 1,
  mining_exp BIGINT UNSIGNED NOT NULL DEFAULT 0,

  map_id VARCHAR(64) NOT NULL DEFAULT 'polaris_tundra',
  map_x SMALLINT UNSIGNED NOT NULL DEFAULT 66,
  map_y SMALLINT UNSIGNED NOT NULL DEFAULT 20,
  map_z TINYINT UNSIGNED NOT NULL DEFAULT 1,

  steps_to_encounter TINYINT UNSIGNED NOT NULL DEFAULT 12,

  mastery_total INT UNSIGNED NOT NULL DEFAULT 0,
  mastery_used INT UNSIGNED NOT NULL DEFAULT 0,

  PRIMARY KEY (user_id),

  CONSTRAINT fk_rpg_user
    FOREIGN KEY (user_id) REFERENCES users(id)
    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- USER PASSWORDS (SECURITY)
-- =========================================================

DROP TABLE IF EXISTS user_auth;
CREATE TABLE user_auth (
  user_id INT UNSIGNED NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL,

  PRIMARY KEY (user_id),

  CONSTRAINT fk_password_user
    FOREIGN KEY (user_id) REFERENCES users(id)
    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- USER BANS (MODERATION)
-- =========================================================

CREATE TABLE user_bans (
  user_id INT UNSIGNED NOT NULL,

  banned_by INT UNSIGNED DEFAULT NULL,
  banned_on INT UNSIGNED DEFAULT NULL,

  rpg_ban TINYINT(1) NOT NULL DEFAULT 0,
  rpg_reason TEXT,
  rpg_notes TEXT,
  rpg_until INT UNSIGNED DEFAULT NULL,

  chat_ban TINYINT(1) NOT NULL DEFAULT 0,
  chat_reason TEXT,
  chat_notes TEXT,
  chat_until INT UNSIGNED DEFAULT NULL,

  PRIMARY KEY (user_id),

  KEY idx_banned_by (banned_by),

  CONSTRAINT fk_ban_user
    FOREIGN KEY (user_id) REFERENCES users(id)
    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- USER REPORTS (MODERATION SYSTEM)
-- =========================================================
CREATE TABLE user_reports (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,

  reported_user_id INT UNSIGNED NOT NULL,
  reported_by INT UNSIGNED NOT NULL,

  reason TEXT NOT NULL,
  created_at INT UNSIGNED NOT NULL,

  status TINYINT UNSIGNED NOT NULL DEFAULT 1,

  PRIMARY KEY (id),

  KEY idx_reported_user (reported_user_id),
  KEY idx_reported_by (reported_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- USER POKEMON (OWNERSHIP, STATS, METADATA)
-- =========================================================
CREATE TABLE user_pokemon (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  pokedex_id SMALLINT UNSIGNED NOT NULL,
  alt_id SMALLINT UNSIGNED NOT NULL DEFAULT 0,

  name VARCHAR(50) DEFAULT NULL,
  forme VARCHAR(16) DEFAULT NULL,

  type enum('Normal','Shiny') NOT NULL DEFAULT 'Normal',

  location enum('Roster','Box','Sold','Trade') NOT NULL DEFAULT 'Box',
  slot TINYINT UNSIGNED NOT NULL DEFAULT 0,

  item INT UNSIGNED NOT NULL DEFAULT 0,

  owner_current INT UNSIGNED NOT NULL,
  owner_original INT UNSIGNED DEFAULT NULL,

  gender enum('Female','Male','Genderless','(?)') NOT NULL DEFAULT '(?)',

  experience INT UNSIGNED NOT NULL DEFAULT 0,

  iv_hp TINYINT UNSIGNED NOT NULL DEFAULT 0,
  iv_attack TINYINT UNSIGNED NOT NULL DEFAULT 0,
  iv_defense TINYINT UNSIGNED NOT NULL DEFAULT 0,
  iv_special_attack TINYINT UNSIGNED NOT NULL DEFAULT 0,
  iv_special_defense TINYINT UNSIGNED NOT NULL DEFAULT 0,
  iv_speed TINYINT UNSIGNED NOT NULL DEFAULT 0,

  ev_hp TINYINT UNSIGNED NOT NULL DEFAULT 0,
  ev_attack TINYINT UNSIGNED NOT NULL DEFAULT 0,
  ev_defense TINYINT UNSIGNED NOT NULL DEFAULT 0,
  ev_special_attack TINYINT UNSIGNED NOT NULL DEFAULT 0,
  ev_special_defense TINYINT UNSIGNED NOT NULL DEFAULT 0,
  ev_speed TINYINT UNSIGNED NOT NULL DEFAULT 0,

  nature enum('Lonely','Adamant','Naughty','Brave','Bold','Impish','Lax','Relaxed','Modest','Mild','Rash','Quiet','Calm','Gentle','Careful','Sassy','Timid','Hasty','Jolly','Naive','Bashful','Docile','Hardy','Quirky','Serious') NOT NULL DEFAULT 'Lonely',
  ability VARCHAR(42) DEFAULT NULL,

  happiness TINYINT UNSIGNED NOT NULL DEFAULT 70,

  trade_interest enum('No','Undecided','Yes') NOT NULL DEFAULT 'Undecided',

  challenge_status TINYINT UNSIGNED NOT NULL DEFAULT 0,
  frozen TINYINT UNSIGNED NOT NULL DEFAULT 0,

  move_1 VARCHAR(64) NOT NULL DEFAULT 'absorb',
  move_2 VARCHAR(64) NOT NULL DEFAULT 'growl',
  move_3 VARCHAR(64) NOT NULL DEFAULT 'agility',
  move_4 VARCHAR(64) NOT NULL DEFAULT 'tackle',

  nickname VARCHAR(69) DEFAULT NULL,
  biography TEXT DEFAULT NULL,

  created_at INT UNSIGNED NOT NULL,
  created_location VARCHAR(100) DEFAULT NULL,
  created_level INT UNSIGNED NOT NULL DEFAULT 5,

  PRIMARY KEY (id),

  -- 🔥 CRITICAL INDEXES
  KEY idx_owner_location (owner_current, location),
  KEY idx_owner_slot (owner_current, slot),
  KEY idx_owner_trade (owner_current, trade_interest),

  KEY idx_pokedex (pokedex_id),

  -- Optional filtering indexes
  KEY idx_type (type),
  KEY idx_created (created_at),

  -- Move relationship
  KEY `idx_move_1` (`move_1`),
  KEY `idx_move_2` (`move_2`),
  KEY `idx_move_3` (`move_3`),
  KEY `idx_move_4` (`move_4`),

  CONSTRAINT `fk_user_pokemon_move_1`
      FOREIGN KEY (`move_1`)
      REFERENCES `api_moves` (`id`)
      ON DELETE SET NULL,

  CONSTRAINT `fk_user_pokemon_move_2`
      FOREIGN KEY (`move_2`)
      REFERENCES `api_moves` (`id`)
      ON DELETE SET NULL,

  CONSTRAINT `fk_user_pokemon_move_3`
      FOREIGN KEY (`move_3`)
      REFERENCES `api_moves` (`id`)
      ON DELETE SET NULL,

  CONSTRAINT `fk_user_pokemon_move_4`
      FOREIGN KEY (`move_4`)
      REFERENCES `api_moves` (`id`)
      ON DELETE SET NULL;

  CONSTRAINT fk_pokemon_owner_current
    FOREIGN KEY (owner_current) REFERENCES users(id)
    ON DELETE CASCADE,

  CONSTRAINT fk_pokemon_owner_original
    FOREIGN KEY (owner_original) REFERENCES users(id)
    ON DELETE SET NULL

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



-- =========================================================
-- POKEDEX DATA ENTRIES
-- =========================================================
CREATE TABLE `api_pokedex` (
  `id` int(11) NOT NULL,
  `pokedex_id` smallint(4) NOT NULL DEFAULT 0,
  `alt_id` smallint(2) NOT NULL DEFAULT 0,
  `pokemon` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'UNKNOWN',
  `forme` varchar(20) DEFAULT NULL,
  `type_primary` enum('None','Normal','Water','Fire','Grass','Electric','Ground','Flying','Fighting','Psychic','Dark','Ghost','Bug','Rock','Ice','Steel','Dragon','Poison','Fairy') NOT NULL DEFAULT 'None',
  `type_secondary` enum('None','Normal','Water','Fire','Grass','Electric','Ground','Flying','Fighting','Psychic','Dark','Ghost','Bug','Rock','Ice','Steel','Dragon','Poison','Fairy') NOT NULL DEFAULT 'None',
  `ability_1` varchar(25) DEFAULT NULL,
  `ability_2` varchar(25) DEFAULT NULL,
  `ability_hidden` varchar(25) DEFAULT NULL,
  `base_hp` smallint(4) NOT NULL,
  `base_attack` smallint(4) NOT NULL,
  `base_defense` smallint(4) NOT NULL,
  `base_sp_attack` smallint(4) NOT NULL,
  `base_sp_defense` smallint(4) NOT NULL,
  `base_speed` smallint(4) NOT NULL,
  `hp_ev_yield` smallint(1) NOT NULL,
  `attack_ev_yield` smallint(1) NOT NULL,
  `defense_ev_yield` smallint(1) NOT NULL,
  `sp_attack_ev_yield` smallint(1) NOT NULL,
  `sp_defense_ev_yield` smallint(1) NOT NULL,
  `speed_ev_yield` smallint(1) NOT NULL,
  `male_odds` float NOT NULL,
  `female_odds` float NOT NULL,
  `genderless_odds` float NOT NULL,
  `height` int(5) NOT NULL,
  `weight` int(5) NOT NULL,
  `catch_rate` smallint(3) NOT NULL,
  `egg_cycles` smallint(3) NOT NULL,
  `exp_yield` smallint(3) NOT NULL,
  `base_happiness` smallint(3) NOT NULL,
  `egg_group_1` varchar(20) NOT NULL,
  `egg_group_2` varchar(20) NOT NULL,
  `is_baby` varchar(5) NOT NULL,
  `is_mythical` varchar(5) NOT NULL,
  `is_legendary` varchar(5) NOT NULL,
  `sort_order` smallint(4) NOT NULL,

  PRIMARY KEY (id),

  UNIQUE KEY uq_pokedex (pokedex_id, alt_id),

  KEY idx_name (pokemon),
  KEY idx_forme (forme),
  KEY idx_type (type_primary, type_secondary),

  KEY idx_egg_groups (egg_group_1, egg_group_2)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


--
-- AUTO_INCREMENT for table `api_pokedex`
--
ALTER TABLE `api_pokedex`
  MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=1119;
COMMIT;

-- =========================================================
-- Pokemon Moves API
-- =========================================================

DROP TABLE IF EXISTS `api_moves`;
CREATE TABLE `api_moves` (
  `id` varchar(64) NOT NULL,
  `name` varchar(128) DEFAULT NULL,
  `type` varchar(32) DEFAULT NULL,
  `category` varchar(32) DEFAULT NULL,
  `basePower` int(11) DEFAULT NULL,
  `accuracy` varchar(32) DEFAULT NULL,
  `pp` int(11) DEFAULT NULL,
  `priority` int(11) DEFAULT NULL,
  `target` varchar(64) DEFAULT NULL,
  `desc` text DEFAULT NULL,
  `shortDesc` text DEFAULT NULL,
  `flags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`flags`)),
  `secondary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`secondary`)),
  `secondaries` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`secondaries`)),
  `drain` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`drain`)),
  `boosts` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`boosts`)),
  `self` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`self`)),
  `selfBoost` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`selfBoost`)),
  `condition` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`condition`)),
  `volatileStatus` varchar(64) DEFAULT NULL,
  `status` varchar(64) DEFAULT NULL,
  `weather` varchar(64) DEFAULT NULL,
  `terrain` varchar(64) DEFAULT NULL,
  `pseudoWeather` varchar(64) DEFAULT NULL,
  `heal` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`heal`)),
  `recoil` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`recoil`)),
  `multihit` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`multihit`)),
  `raw_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`raw_json`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


ALTER TABLE `api_moves`
  ADD PRIMARY KEY (`id`);
COMMIT;

UPDATE `api_moves` SET `accuracy` = 100 WHERE `accuracy` = 1;


-- =========================================================
-- user_items - all items owned by all users
-- =========================================================

DROP TABLE IF EXISTS `user_items`;

CREATE TABLE `user_items` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `item_identifier` VARCHAR(64) NOT NULL,
  `name` VARCHAR(128) NOT NULL,
  `owner_id` INT UNSIGNED NOT NULL,
  `quantity` INT(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY idx_user_items_item_identifier (`item_identifier`),
  KEY idx_user_items_owner_id (`owner_id`),
  CONSTRAINT fk_api_item_identifier FOREIGN KEY (`item_identifier`)
    REFERENCES `api_items`(`identifier`)
    ON UPDATE CASCADE
    ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =========================================================
-- COMMIT
-- =========================================================

COMMIT;
